1	// The scheduler entrypoint's orchestration core (per-project-scheduling DESIGN
2	// §3). The vendored hourly Action runs this: decide due slots from the run
3	// ledger, discover active tasks, collect only the signals the due tasks declare,
4	// run each precondition, and either dispatch agent work as a `ready-for-agent`
5	// issue or (for `agent_model: none`) run the worker inline.
6	//
7	// This module is the DECISION core, kept injectable so it tests with fakes: the
8	// GitHub I/O (the Actions run-ledger read for `lastSuccess`, the signal
9	// collectors, the issue search/create) is supplied by the thin CLI shell around
10	// `planRun`. The "should this run" verdict is always code here — never the
11	// shell's judgment (the same split the fleet planner uses).
12	
13	import { pathToFileURL } from 'node:url';
14	import { dueSlots, mostRecentSlot } from './slots.mjs';
15	import {
16	  planDispatch, dispatchTitle, dispatchBody, DISPATCH_PREFIX, READY_LABEL, NEEDS_HUMAN_LABEL,
17	  SCHEDULER_LABELS, readyLabelForScope, escalationLabel,
18	} from './dispatch.mjs';
19	import { isAgentless } from './model-map.mjs';
20	import { isDormant } from '../checks/helpers/repo-context.mjs';
21	import { renderTaskRuns } from './run-record.mjs';
22	import { localSignalContext } from './signals/local.mjs';
23	import { runPrework, preworkFailure, agentRequestPath, clearAgentRequest, agentRequested, readAgentRequest } from './prework.mjs';
24	
25	// The due tasks, each paired with the slot it runs under. Union the discovered
26	// tasks' frequencies, ask slots which are due (run-ledger math), then map due
27	// frequencies back to their tasks. A task whose frequency isn't due drops out.
28	//
29	// A run carrying FORCE_TASKS evaluates ONLY the forced tasks (#749). The operator
30	// pressed a button that names specific work; running whatever else happened to be
31	// due at that minute alongside it would make the button's effect depend on WHEN it
32	// was pressed — and a fleet fan-out that fires twenty members' schedulers must mean
33	// exactly one task in each, not one task plus each member's coincident backlog.
34	// The skipped due work is not lost: the forced run is excluded from the run ledger's
35	// success watermark question only in the sense that any due slot it did not run
36	// stays due, and the next scheduled run picks it up (dueSlots' most-recent-slot
37	// math never needed this run to happen).
38	export function computeDueTaskSlots(tasks, schedule, now, lastSuccess, forced = []) {
39	  if (forced.length) {
40	    // Each forced task runs under its most-recent slot even though that slot has
41	    // already been run (or, for a `manual` task, never fires on its own at all).
42	    // This gate is the reason forcing has to live here: the due list is computed
43	    // BEFORE any precondition, so a task whose slot has passed is never looked at
44	    // again — and a mid-day forced run is the only kind that matters (#515).
45	    // `planRun` then skips its precondition outright.
46	    return tasks.filter((t) => forced.includes(t.id)).map((task) => {
47	      const s = mostRecentSlot(task.decl.frequency, schedule, now);
48	      return { task, slotId: s.id, slotTime: s.time, forced: true };
49	    });
50	  }
51	  const frequencies = [...new Set(tasks.map((t) => t.decl.frequency))];
52	  const due = new Map(dueSlots(frequencies, schedule, now, lastSuccess).map((d) => [d.frequency, d]));
53	  const out = [];
54	  for (const task of tasks) {
55	    const slot = due.get(task.decl.frequency);
56	    if (slot) out.push({ task, slotId: slot.slotId, slotTime: slot.slotTime });
57	  }
58	  return out;
59	}
60	
61	// The verdict a forced task gets INSTEAD of its precondition. The context line
62	// is generic on purpose — it names the mechanism, not the task — and it is there
63	// because a dispatch issue's Context is the agent's binding scope: a forced
64	// dispatch that carried none would read as a scope of nothing, and the agent
65	// should know it arrived by a hand-started run rather than a met condition.
66	const FORCED_VERDICT = Object.freeze({
67	  run: true,
68	  reason: 'forced by FORCE_TASKS on a manual scheduler run — its precondition was not evaluated',
69	  context: Object.freeze(['This run was forced manually (FORCE_TASKS on a workflow_dispatch); the task\'s own precondition was not evaluated, so nothing here asserts there is work to do. Do only what the task file specifies, and converge to a no-op if there is nothing.']),
70	});
71	
72	// The task ids a manual run forced, out of the opaque override bag. This is the
73	// ONE key the engine reads from that bag, and it is deliberately generic: it
74	// learns "run these task ids", never what any of them do. No task declaration
75	// mentions forcing, and no precondition is consulted for a forced task — an id
76	// matching no discovered task simply forces nothing.
77	export function forcedTaskIds(overrides = {}) {
78	  return String(overrides.FORCE_TASKS ?? '').split(',').map((s) => s.trim()).filter(Boolean);
79	}
80	
81	// The union of signal names the due tasks declare — the scheduler collects only
82	// these, so a non-daily slot never pays for daily tasks' signals (DESIGN §3.3).
83	export function signalsUnion(dueTaskSlots) {
84	  const names = new Set();
85	  for (const { task } of dueTaskSlots) for (const name of task.decl.precondition_signals) names.add(name);
86	  return [...names];
87	}
88	
89	// The signal-collection lookback: the widest due task's period plus 1h slack
90	// (DESIGN §3.3). Stateless fixed lookback — overlap is absorbed by dedupe.
91	const FREQUENCY_MS = {
92	  hourly: 3600e3, 'daily-2h': 86400e3, 'daily-1h': 86400e3, daily: 86400e3,
93	  'daily+1h': 86400e3, weekly: 7 * 86400e3, monthly: 31 * 86400e3,
94	};
95	export function windowStart(dueTaskSlots, now) {
96	  const widest = Math.max(0, ...dueTaskSlots.map(({ task }) => FREQUENCY_MS[task.decl.frequency] ?? 86400e3));
97	  return new Date(new Date(now).getTime() - widest - 3600e3).toISOString();
98	}
99	
100	// Run one task's precondition in isolation (DESIGN §3.4). A throwing
101	// precondition converges to a skip with the error recorded — it never sinks the
102	// rest of the run; the CLI escalates a thrown precondition to a workflow-failure
103	// issue separately.
104	//
105	// `exclusive` is the verdict's optional CLAIM ON THE WHOLE RUN (see planRun): a
106	// task saying "if I run, I run alone this cycle". Normalized to a boolean here,
107	// like every other field, so a precondition that omits it is simply not claiming.
108	export function runPrecondition(task, signals, packConfig) {
109	  try {
110	    const v = task.decl.precondition(signals, packConfig) ?? {};
111	    return {
112	      run: v.run === true,
113	      exclusive: v.exclusive === true,
114	      reason: v.reason ?? '',
115	      context: Array.isArray(v.context) ? v.context : [],
116	    };
117	  } catch (e) {
118	    return { run: false, exclusive: false, reason: `precondition threw: ${e.message}`, context: [], error: e.message };
119	  }
120	}
121	
122	// What a task deferred by another task's exclusive claim is told, in the run
123	// summary and the run record. Generic on purpose — it names the claimant, never
124	// what the claimant does, because the engine does not know.
125	//
126	// "Its next slot", not "the next run": due-ness is `slotTime ∈ (lastSuccess,
127	// now]` and this run succeeds, so the watermark moves past the slot that was
128	// deferred. A deferred daily task runs tomorrow, a weekly one next week. That is
129	// the price of the claim and it is stated where a person reading the run sees it.
130	export const deferredByClaim = (claimants) =>
131	  `deferred — ${claimants.join(', ')} claimed this run exclusively; this slot is spent, the task runs again at its next slot`;
132	
133	// A human-readable job-summary line per evaluated task — the observability the
134	// old plan.json gave (DESIGN §3.6).
135	export function renderSummary(evaluations) {
136	  return evaluations.map((e) => {
137	    const verb = !e.run ? 'skip' : e.deferred ? 'defer' : e.inline ? 'run-inline' : e.dispatch?.action ?? 'run';
138	    const forced = e.forced ? ' (forced)' : '';
139	    const claim = e.exclusive ? ' (exclusive)' : '';
140	    // A lane held for triage (#821) says so ahead of the precondition's reason,
141	    // which otherwise always wins and describes the work that WOULD have run. The
142	    // hold is the one suppression a person has to act on, and a summary that
143	    // reports only "there was work" is how it stayed invisible for three weeks.
144	    const why = (e.dispatch?.escalated && e.dispatch.reason) || e.deferred || e.reason || e.dispatch?.reason || '';
145	    return `- ${e.pack}/${e.task} [${e.slotId}]${forced}${claim} ${verb} — ${why}`.trimEnd();
146	  }).join('\n');
147	}
148	
149	// Orchestrate one scheduler run into a set of decisions — the reusable core the
150	// CLI wraps with real GitHub I/O. Injected seams:
151	//   collectSignals(names) -> signals object (the declared union, collected once)
152	//   packConfigFor(packId) -> that pack's entry config from .claudinite-checks.json
153	//   existingIssuesFor(pack, task) -> the task family's issues [{number,title,state,labels}]
154	// Returns `{ evaluations }`: one record per due task with its precondition
155	// verdict and, when it runs, either an inline marker (agent_model: none) or a
156	// dispatch decision (planDispatch).
157	//
158	// DORMANCY IS THE FIRST GATE, ahead of the due-slot math and every task's own
159	// precondition (`config`, the repo's loaded declaration). A dormant project has
160	// said it is out of the recurring work: it is not that each task happens to have
161	// nothing to do, it is that no task is asked. Putting the gate here rather than
162	// in each precondition is the whole point — every task, canon and local, present
163	// and future, is covered by one decision nothing has to opt into, and a task
164	// never learns that dormancy exists.
165	//
166	// THE EXCLUSIVE CLAIM (owner, 2026-08-01). A precondition may return `exclusive: true`
167	// alongside `run: true`: "if I run this cycle, I run ALONE". Every other due task
168	// whose precondition also said run is deferred — no prework, no dispatch
169	// issue, no inline work — and the run does that one task's work and nothing else.
170	//
171	// This exists because the hourly cron is not hourly (github-actions-scheduling:
172	// GitHub drops and delays scheduled fires freely). The daily anchors stage the
173	// nightly chain by an HOUR each — `update` at 02:00 converges the mount before
174	// the 03:00 and 04:00 tasks read it — and that staging holds only while the fires
175	// land roughly on time. A run that fires at 05:40 after three dropped fires finds
176	// all four daily slots due at once and dispatches them together, so the task whose
177	// whole job is to repair what the others run against runs BESIDE them instead of
178	// before them. The claim restores the ordering the anchors were meant to express,
179	// on exactly the runs where the anchors failed to.
180	//
181	// It is deliberately a task's decision and not the engine's: the engine learns
182	// "this verdict claims the run", never which task claims or why — the same
183	// separation `forcedTaskIds` keeps, and the reason nothing here mentions
184	// the mount-converging task. A task that never returns `exclusive` cannot be affected as a
185	// claimant, only as a deferree.
186	//
187	// A FORCED task is exempt from deferral (and cannot claim: FORCED_VERDICT carries
188	// no `exclusive`). Forcing is an operator decision already made on a hand-started
189	// run; a claim silently swallowing the task the operator asked for would make that
190	// run do nothing it was started for.
191	export async function planRun({
192	  tasks, schedule, now, lastSuccess, overrides = {}, config = {}, runId = null,
193	  collectSignals, packConfigFor = () => ({}), existingIssuesFor = async () => [],
194	}) {
195	  if (isDormant(config)) return { evaluations: [], dormant: true };
196	  // `overrides` arrives as a parameter rather than out of `signals` because the
197	  // due list is what decides which signals get collected — the bag has to be
198	  // known before the collection it would otherwise be part of.
199	  const dueList = computeDueTaskSlots(tasks, schedule, now, lastSuccess, forcedTaskIds(overrides));
200	  const signals = await collectSignals(signalsUnion(dueList));
201	
202	  // Pass 1 — every due task's verdict, and nothing else. Preconditions are pure
203	  // and cheap, and a claim is only knowable once they have ALL spoken, so no
204	  // issue search and no dispatch decision may happen before this pass completes.
205	  //
206	  // A FORCED task does not consult its precondition at all. "Forced" is a
207	  // decision the operator already made, so asking the task whether it agrees is
208	  // both redundant and a way for the answer to be no — and a task that could
209	  // veto a force would need to know forcing exists, which is exactly the
210	  // coupling this mechanism avoids. Nothing in a task declaration mentions
211	  // forcing; the engine owns it end to end.
212	  const verdicts = dueList.map(({ task, slotId, forced }) => ({
213	    task, slotId, forced,
214	    pre: forced ? FORCED_VERDICT : runPrecondition(task, signals, packConfigFor(task.pack)),
215	  }));
216	
217	  // The claimants: running tasks that asked for the run to themselves. More than
218	  // one is not a conflict to arbitrate — they all run and everything else defers,
219	  // which is the only reading that needs no priority order between packs.
220	  const claimants = verdicts.filter((v) => v.pre.run && v.pre.exclusive).map((v) => `${v.task.pack}/${v.task.id}`);
221	
222	  const evaluations = [];
223	  for (const { task, slotId: dueSlot, forced, pre } of verdicts) {
224	    // A FORCED dispatch carries a per-run marker in its slot id. The exactly-once
225	    // guard keys on the (task, slot) title, and a forced run's whole point is to
226	    // re-run a slot the schedule already ran — without the marker, planDispatch's
227	    // state=all title match silently skipped exactly the dispatch the operator
228	    // asked for. The marker keeps every title unique and every record attributable
229	    // to the hand-started run that caused it. At-most-one-open still applies: a
230	    // forced run never stacks a second dispatch on one that is still open.
231	    const slotId = forced && runId !== null ? `${dueSlot}~f${runId}` : dueSlot;
232	    const rec = {
233	      pack: task.pack, task: task.id, slotId,
234	      model: task.decl.agent_model, outcome: task.decl.expected_outcome,
235	      run: pre.run, reason: pre.reason, context: pre.context,
236	    };
237	    if (forced) rec.forced = true;
238	    if (pre.error) rec.error = pre.error;
239	    if (pre.run) {
240	      if (pre.exclusive) rec.exclusive = true;
241	      // Deferred by someone else's claim: the record keeps `run: true` (its
242	      // precondition DID say there was work) and carries no dispatch, no inline
243	      // and no prework flag, so every actor downstream — the CLI action
244	      // loop, the run record, the summary — reads it as work that was wanted and
245	      // did not happen, not as a skip.
246	      if (claimants.length && !pre.exclusive && !forced) {
247	        rec.deferred = deferredByClaim(claimants);
248	        evaluations.push(rec);
249	        continue;
250	      }
251	      // Declared prework runs as a subprocess BEFORE the agentic phase
252	      // (DESIGN §3) — flagged here (pure) for the summary; the CLI shell executes
253	      // it. An agentless task is prework-only; an agentful one hands off to
254	      // the agentic phase after prework succeeds.
255	      if (task.decl.prework) rec.prework = true;
256	      if (isAgentless(task.decl.agent_model)) {
257	        // agent_model: none — no agent and no dispatch issue on success. A task with
258	        // no prework runs the legacy inline worker; with prework it is
259	        // the subprocess above.
260	        rec.inline = true;
261	      } else {
262	        const existing = await existingIssuesFor(task.pack, task.id);
263	        // Route the dispatch by the task's (deprecated, lingering) session_scope —
264	        // absent on everything but the canon's curation tasks, so almost every
265	        // dispatch rides the ordinary ready label.
266	        const readyLabel = readyLabelForScope(task.decl.session_scope);
267	        rec.dispatch = planDispatch({ existing, pack: task.pack, task: task.id, slotId, readyLabel });
268	      }
269	    }
270	    evaluations.push(rec);
271	  }
272	  return { evaluations };
273	}
274	
275	// The opaque override bag a MANUAL run may carry (`workflow_dispatch` input →
276	// `CLAUDINITE_OVERRIDES`). GitHub cannot declare arbitrary named inputs, so the
277	// workflow takes ONE free-form string and this splits it into keys.
278	//
279	// Exactly one key is understood: `FORCE_TASKS` (see `forcedTaskIds`), and it is
280	// understood GENERICALLY — "run these task ids", never what any of them do. No
281	// task declaration mentions forcing and no precondition is consulted for a forced
282	// task, so the scheduler never learns what the update task is and that task never
283	// learns that forcing exists. Anything else in the bag is parsed and ignored,
284	// which is what leaves room for a future override without a schema.
285	//
286	// `A=1,B=2`, newline-separated, or bare `A` (⇒ `'true'`). Values stay STRINGS with
287	// no truthiness coercion: a task compares against the literal it documents, so
288	// `FORCE_X=false` can never read as "the key is present, therefore on".
289	export function parseOverrides(raw) {
290	  const out = {};
291	  for (const part of String(raw ?? '').split(/[,\n]/)) {
292	    const token = part.trim();
293	    if (!token) continue;
294	    const eq = token.indexOf('=');
295	    if (eq === -1) out[token] = 'true';
296	    else out[token.slice(0, eq).trim()] = token.slice(eq + 1).trim();
297	  }
298	  return out;
299	}
300	
301	// The `ctx` every signal collector reads (DESIGN §3.3) — the already-resolved
302	// facts a collector may not go and fetch for itself, built once per run and
303	// handed to `collectSignals`. Exported so the construction itself is testable:
304	// the collectors' `ctx.X ?? null` seam makes them unit-testable with a hand-built
305	// ctx, which is exactly why a key nothing here populates can read as "collector
306	// works" forever. Assert against THIS, not a hand-built shape.
307	// `root` is the Action-side checkout: the manifest version, the local-pack
308	// presence and the configured retention are all read from it (signals/local.mjs),
309	// because a scheduled run already has the tree on disk and an API round-trip
310	// would buy nothing.
311	export function buildSignalContext({ root, repo, defaultBranch, now, sinceIso, config, fleet = null, packConfigFor = () => ({}) }) {
312	  const local = localSignalContext(root, { packIds: config.packs ?? [], packConfigFor });
313	  return {
314	    repo, defaultBranch, now, sinceIso, config,
315	    activePacks: config.packs, fleet,
316	    manifestVersion: local.manifestVersion,
317	    hasLocalPacks: local.hasLocalPacks,
318	    retentionDays: local.retentionDays,
319	  };
320	}
321	
322	// --- CLI: the thin I/O shell the vendored workflow invokes -------------------
323	// Wires the run-ledger read, signal collectors, and issue I/O around planRun,
324	// then acts on each decision (file a labeled dispatch issue, or run an inline
325	// worker) and prints the job summary. All GitHub access here is the Action's
326	// GITHUB_TOKEN — the one sanctioned non-MCP surface (DESIGN §10).
327	
328	// The task family's issues (state=all) via the search API, filtered to exact
329	// prefix — the input planDispatch's exactly-once / at-most-one-live guards read.
330	//
331	// `labels` is load-bearing, not extra: the guard distinguishes a live claim from a
332	// `needs-human` terminal by label (#821), and a projection that drops them makes
333	// every open issue read as live — the pure rule stays green on fixtures while the
334	// shell feeds it a shape in which the distinction cannot exist. Exported for the
335	// test that pins exactly that.
336	export async function existingIssuesViaSearch(gh, repo, pack, task) {
337	  const q = encodeURIComponent(`repo:${repo} in:title "${DISPATCH_PREFIX} ${pack}/${task}"`);
338	  const { status, json } = await gh(`/search/issues?q=${q}&per_page=100`);
339	  if (status !== 200 || !Array.isArray(json?.items)) return [];
340	  const prefix = `${DISPATCH_PREFIX} ${pack}/${task} `;
341	  return json.items
342	    .filter((i) => `${(i.title ?? '').trim()} `.startsWith(prefix))
343	    .map((i) => ({ number: i.number, title: i.title, state: i.state, labels: i.labels ?? [] }));
344	}
345	
346	// DISPATCH-ISSUE MAINTENANCE DOES NOT LIVE HERE (owner, 2026-08-06). The
347	// scheduler CREATES task issues and nothing else about their afterlife: the
348	// stale-escalation, dead-claim and re-arm recovery that used to run as a pass at
349	// the end of every scheduler run is a third, separate JANITOR responsibility —
350	// an ordinary daily task on this same machinery (the engine does not know which
351	// pack carries it, same as every task). Scheduler creates, executor executes its
352	// one issue, janitor cleans up and assesses health. The pure rules stay in
353	// dispatch.mjs; the janitor's worker is the only I/O shell over them.
354	
355	// Ensure the dispatch labels exist before any is applied — GitHub 422s when you
356	// apply an unknown label (it never creates one on demand), so the scheduler, as the
357	// thing that assigns them, guarantees them here. Idempotent (201 created / 422 already
358	// exists are both success) and self-healing (a deleted label reappears next run), which
359	// is why no separate one-off label-creation step is needed. Exported for the run tests.
360	export async function ensureLabels(gh, repo, labels) {
361	  for (const { name, color, description } of labels) {
362	    const res = await gh(`/repos/${repo}/labels`, { method: 'POST', body: { name, color, description } });
363	    if (res.status === 201) continue;                       // created to spec — nothing further
364	    if (res.status === 422) {
365	      // The NAME is taken; that says nothing about the colour or description. A
366	      // label GitHub auto-created (applying an unknown name to an issue mints it
367	      // grey `ededed`, no description) would keep those defaults for good, because
368	      // POST 422s forever. So reconcile the shape, not just the existence — that
369	      // is what makes the self-healing claim above true for drift and not only for
370	      // deletion. PATCH is idempotent: an already-correct label is a no-op write.
371	      const fix = await gh(`/repos/${repo}/labels/${encodeURIComponent(name)}`, {
372	        method: 'PATCH', body: { color, description },
373	      });
374	      if (fix.status !== 200) console.log(`! could not reconcile label "${name}": ${fix.status}`);
375	      continue;
376	    }
377	    console.log(`! could not ensure label "${name}": ${res.status}`);
378	  }
379	}
380	
381	async function main() {
382	  const { makeGh, lastSuccessTime, actionRepoContext } = await import('./signals/gh.mjs');
383	  const { collectSignals } = await import('./signals/index.mjs');
384	  const { discoverTasks } = await import('./discover.mjs');
385	  const { loadConfig } = await import('../checks/helpers/repo-context.mjs');
386	
387	  const root = process.cwd();
388	  const { repo, defaultBranch } = actionRepoContext();
389	  if (!repo) { console.error('GITHUB_REPOSITORY not set — not in an Actions context'); process.exit(1); }
390	  const gh = makeGh();
391	  const config = loadConfig(root);
392	
393	  // The dormancy gate, before ANY of it: the run-ledger read, the task discovery,
394	  // the signal collection, the issue I/O, the dispatch maintenance. planRun holds
395	  // the same verdict (one predicate, both call sites) and would return an empty
396	  // plan — but a dormant repo should not pay for the reads that produce it, and
397	  // the maintenance pass below writes to issues, which is exactly the ceremony
398	  // dormancy exists to stop.
399	  //
400	  // Exit 0, deliberately. The run enters the success ledger and the watermark
401	  // advances past these slots, so waking a project up does NOT replay the months
402	  // it slept through — it simply starts scheduling again from now. Slots skipped
403	  // while dormant are skipped on purpose, not deferred.
404	  if (isDormant(config)) {
405	    console.log('## Claudinite scheduler\n');
406	    console.log('- this project declares itself dormant ("dormant": true in .claudinite-checks.json) — no tasks evaluated, no work dispatched');
407	    return;
408	  }
409	
410	  const { tasks, errors } = await discoverTasks(root, config);
411	  for (const e of errors) console.log(`! ${e.what}`);
412	
413	  const now = new Date();
414	  // The watermark IS the scheduler's state, so a run that cannot read it cannot
415	  // compute due-ness at all — and every guess is wrong in a way nobody sees:
416	  // "assume fresh" re-fires the first-run set on a mature repo, "assume now"
417	  // silently eats the slots it skipped. Fail the run instead. It must exit
418	  // NON-ZERO: an exit-0 abort would enter the success ledger and advance the
419	  // watermark past the very slots it declined to evaluate. Failing leaves the
420	  // watermark untouched, so the next successful run catches them up (#522).
421	  let lastSuccess;
422	  try {
423	    lastSuccess = await lastSuccessTime(gh, repo);
424	  } catch (e) {
425	    console.error(`${e.message} — cannot compute due slots; failing this run so the next one catches up`);
426	    process.exit(1);
427	  }
428	  const schedule = config.taskScheduler;
429	
430	  const due = computeDueTaskSlots(tasks, schedule, now, lastSuccess);
431	  const sinceIso = windowStart(due, now);
432	
433	  // The fleet aggregate (canon-only, DESIGN §3.3) is expensive — a full
434	  // enumeration over the fleet PAT — so build it ONLY when a due task actually
435	  // declares the `fleet` signal, and only when FLEET_GITHUB_TOKEN is set (the
436	  // canon repo with the census credential). Otherwise ctx.fleet stays null and
437	  // the collector returns null, so a fleet task's precondition skips rather than
438	  // crashes. Enumeration failures are surfaced by readFleet as `{ error }`, not
439	  // thrown — a fleet task treats that as "no work I can prove".
440	  let fleet = null;
441	  if (signalsUnion(due).includes('fleet')) {
442	    const { readFleet, makeFleetGh } = await import('./signals/fleet.mjs');
443	    const fleetGh = makeFleetGh();
444	    if (fleetGh) {
445	      const owner = repo.split('/')[0];
446	      fleet = await readFleet(fleetGh, { owner, canonRepo: repo, sinceIso });
447	      if (fleet.error) console.log(`! fleet enumeration: ${fleet.error}`);
448	    } else {
449	      console.log('- a due task declares the `fleet` signal but FLEET_GITHUB_TOKEN is not set — skipping fleet-scoped tasks');
450	    }
451	  }
452	
453	  const packConfigFor = (packId) => config.packConfig?.[packId] ?? {};
454	
455	  // An override only ever arrives on a hand-started run, and it makes a task run
456	  // that its own precondition would have skipped — so say so in the log. An
457	  // unattended system that can be forced silently is one whose run history stops
458	  // explaining itself.
459	  const overrides = parseOverrides(process.env.CLAUDINITE_OVERRIDES);
460	  const overrideKeys = Object.keys(overrides);
461	  if (overrideKeys.length > 0) {
462	    console.log(`- manual run overrides: ${overrideKeys.map((k) => `${k}=${overrides[k]}`).join(', ')}`);
463	  }
464	
465	  const ctx = buildSignalContext({
466	    root, repo, defaultBranch, now: now.toISOString(), sinceIso, config, fleet, packConfigFor,
467	  });
468	
469	  const { evaluations } = await planRun({
470	    tasks, schedule, now, lastSuccess, overrides, config,
471	    // The per-run marker a FORCED dispatch's slot id carries (see planRun) —
472	    // the Actions run id, unique per hand-started run by the platform.
473	    runId: process.env.GITHUB_RUN_ID ?? null,
474	    collectSignals: (names) => collectSignals(gh, ctx, names),
475	    packConfigFor,
476	    existingIssuesFor: (pack, task) => existingIssuesViaSearch(gh, repo, pack, task),
477	  });
478	
479	  // An exclusive claim makes this run do ONE task's work and defer the rest, so
480	  // say so before the actions rather than leaving it to be inferred from the
481	  // per-task summary lines. An unattended run that quietly drops work it was
482	  // going to do is one whose history stops explaining itself.
483	  const claimed = evaluations.filter((r) => r.exclusive);
484	  const deferred = evaluations.filter((r) => r.deferred);
485	  if (claimed.length) {
486	    console.log(`- ${claimed.map((r) => `${r.pack}/${r.task}`).join(', ')} claimed this run exclusively`
487	      + ` — ${deferred.length} other due task(s) deferred to their next slot`);
488	  }
489	
490	  // Guarantee the dispatch labels exist before we file any labeled issue — when a
491	  // task will dispatch OR will run prework (which may converge to
492	  // needs-human). An idle run pays nothing.
493	  const labelsEnsured = evaluations.some((r) => r.run && (r.prework || (!r.inline && r.dispatch?.action === 'create')));
494	  if (labelsEnsured) await ensureLabels(gh, repo, SCHEDULER_LABELS);
495	
496	  // File the labeled hand-off issue the executor runs (READY_LABEL): first line is
497	  // the task path, body carries the precondition's binding Context (dispatch.mjs).
498	  const fileHandoff = async (rec, taskObj) => {
499	    const title = dispatchTitle({ pack: rec.pack, task: rec.task, slotId: rec.slotId });
500	    const body = dispatchBody({
501	      taskPath: taskObj.taskPath, pack: rec.pack, task: rec.task, slotId: rec.slotId,
502	      context: rec.context,
503	      // What prework made, by identity — the agent's only source for it.
504	      delivered: rec.delivered,
505	      // …and which of its escalation conditions woke the agent, so the agent does not
506	      // have to re-derive that from the repo (and get it wrong).
507	      reason: rec.escalationReason,
508	    });
509	    // The scope-resolved ready label (self vs fleet) from planDispatch — the
510	    // executor routine wired to it runs the task.
511	    const readyLabel = rec.dispatch?.label ?? READY_LABEL;
512	    // …and the escalation code as a label, so the condition is countable and not
513	    // only readable. Minted per code, so it is ensured here rather than in the
514	    // up-front SCHEDULER_LABELS pass, which cannot know which code will fire.
515	    const escalation = escalationLabel(rec.escalationReason?.code);
516	    if (escalation) await ensureLabels(gh, repo, [escalation]);
517	    const labels = escalation ? [readyLabel, escalation.name] : [readyLabel];
518	    const res = await gh(`/repos/${repo}/issues`, { method: 'POST', body: { title, body, labels } });
519	    if (res.status >= 300) console.log(`! failed to file dispatch issue for ${rec.pack}/${rec.task}: ${res.status}`);
520	  };
521	
522	  // Converge a failed prework run to a single open needs-human issue for the
523	  // family — at-most-one-open, so a repeatedly-failing task never spams issues.
524	  const fileNeedsHuman = async (rec, why, extra) => {
525	    const existing = await existingIssuesViaSearch(gh, repo, rec.pack, rec.task);
526	    if (existing.some((i) => i.state === 'open')) {
527	      console.log(`  (an open dispatch issue already covers ${rec.pack}/${rec.task} — not filing another)`);
528	      return;
529	    }
530	    const title = dispatchTitle({ pack: rec.pack, task: rec.task, slotId: rec.slotId });
531	    const body = [
532	      `Prework for \`${rec.pack}/${rec.task}\` (slot \`${rec.slotId}\`) failed and needs human triage.`,
533	      '', `- ${why}`, ...extra.map((e) => `- ${e}`),
534	    ].join('\n') + '\n';
535	    const res = await gh(`/repos/${repo}/issues`, { method: 'POST', body: { title, body, labels: [NEEDS_HUMAN_LABEL] } });
536	    if (res.status >= 300) console.log(`! failed to file needs-human issue for ${rec.pack}/${rec.task}: ${res.status}`);
537	  };
538	
539	  for (const rec of evaluations) {
540	    // `deferred` — another task claimed this run exclusively. The record says the
541	    // precondition wanted work; this is the one place that decides none of it
542	    // happens, so nothing below (prework subprocess, dispatch issue) runs.
543	    if (!rec.run || rec.deferred) continue;
544	    const taskObj = tasks.find((t) => t.pack === rec.pack && t.id === rec.task);
545	    const decl = taskObj.decl;
546	
547	    // Phase 1 — prework (DESIGN §3): run the declared command as a subprocess
548	    // bounded by its timeout, before the agentic phase. Its cwd is the task dir;
549	    // the repo root + slot context ride in via CLAUDINITE_* env.
550	    if (rec.prework) {
551	      // A per-run signal path the worker writes to REQUEST the agent stage
552	      // (conditional handoff, §3). Clear any stale one first so a prior run can't
553	      // spuriously escalate this one.
554	      const requestPath = agentRequestPath(rec);
555	      clearAgentRequest(requestPath);
556	      // The child's own output is echoed live inside a collapsible Actions group, so
557	      // the run log says what the worker did instead of only whether it exited zero.
558	      // Grouped because several tasks can run prework in one run and their output would
559	      // otherwise interleave into one unattributable wall; live because a worker killed
560	      // at its timeout takes any buffered output with it.
561	      console.log(`::group::prework ${rec.pack}/${rec.task} [${rec.slotId}]`);
562	      const result = await runPrework(decl.prework, {
563	        taskDir: taskObj.taskDir,
564	        env: {
565	          ...process.env,
566	          CLAUDINITE_REPO_ROOT: root,
567	          CLAUDINITE_REPO: repo,
568	          CLAUDINITE_DEFAULT_BRANCH: defaultBranch ?? '',
569	          CLAUDINITE_SLOT_ID: rec.slotId,
570	          CLAUDINITE_PACK: rec.pack,
571	          CLAUDINITE_TASK: rec.task,
572	          CLAUDINITE_REQUEST_AGENT: requestPath,
573	        },
574	        timeoutSeconds: decl.prework_timeout,
575	      });
576	      console.log('::endgroup::');
577	      rec.preworkResult = { ok: result.ok, timedOut: result.timedOut, code: result.code };
578	      if (!result.ok) {
579	        const why = preworkFailure(result);
580	        console.log(`! prework ${rec.pack}/${rec.task} [${rec.slotId}]: ${why}`);
581	        const extra = result.stderr?.trim() ? [`stderr tail: ${result.stderr.trim().split('\n').slice(-3).join(' / ')}`] : [];
582	        // Repeat the tail OUTSIDE the group: Actions renders a group collapsed, so a
583	        // failure whose only evidence sits inside one still reads as unexplained.
584	        for (const line of extra) console.log(`  ${line}`);
585	        await fileNeedsHuman(rec, why, extra);
586	        clearAgentRequest(requestPath);
587	        continue; // never hand off to the agentic phase after failed prework
588	      }
589	      // Success. An agentless task is done (no issue on success, as the old inline
590	      // was quiet). An agentful one hands off ONLY when the worker requested the
591	      // agent (conditional escalation, §3): a task that absorbs its work into
592	      // prework stays quiet on the nights nothing needs judgment.
593	      const requested = agentRequested(requestPath);
594	      // Read the payload BEFORE clearing: the artifacts this run created and the
595	      // condition that woke the agent, which the dispatch issue records so the agent
596	      // never has to search for them by name or re-derive why it is there. Both are
597	      // null for a worker that named neither — absence is reported as absence.
598	      const payload = requested ? readAgentRequest(requestPath) : null;
599	      rec.delivered = payload?.delivered ?? null;
600	      rec.escalationReason = payload?.reason ?? null;
601	      clearAgentRequest(requestPath);
602	      rec.agentRequested = requested;
603	      console.log(`prework ${rec.pack}/${rec.task} [${rec.slotId}]: ok${rec.inline ? '' : requested ? ' (agent requested)' : ' (no agent needed)'}`);
604	      if (rec.inline) continue;
605	      if (requested && rec.dispatch?.action === 'create') await fileHandoff(rec, taskObj);
606	      continue;
607	    }
608	
609	    // No prework. An agentless task with no prework does nothing — the
610	    // contract now forbids it (agent_model:none REQUIRES prework, so
611	    // the in-process inline worker path is retired, DESIGN §4). Defensive no-op
612	    // should one slip past validation.
613	    if (rec.inline) {
614	      console.log(`- ${rec.pack}/${rec.task}: agentless with no prework — nothing to run (contract-forbidden)`);
615	      continue;
616	    }
617	    // Agentic task with no prework → today's immediate labeled dispatch.
618	    if (rec.dispatch?.action === 'create') await fileHandoff(rec, taskObj);
619	  }
620	
621	  console.log('## Claudinite scheduler\n');
622	  console.log(renderSummary(evaluations) || '- no tasks due');
623	
624	  // The machine-readable half of the same story (run-record.mjs): one line per due
625	  // task saying what this run DID with it — dispatched an agent, ran it as
626	  // ran prework only, skipped it on its precondition, failed it, or deferred it.
627	  // Printed AFTER the action loop, so each line reports what happened rather than
628	  // what was planned, and read back by the usage fold to count task invocations.
629	  // Nothing else in the scheduler depends on it: this is a record, not a signal.
630	  if (evaluations.length) console.log(`\n${renderTaskRuns(evaluations)}`);
631	}
632	
633	// Run only when invoked directly (the workflow's `node run.mjs`), never on import.
634	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
635	  main().catch((e) => { console.error(e); process.exit(1); });
636	}
