1	// The dispatch issue — how a due (task, slot) becomes exactly-once, bounded,
2	// recoverable agent work (per-project-scheduling DESIGN §4). This module is the
3	// PURE half: issue identity (title/body/parse) and the create / skip / suppress
4	// decision over the issues that already exist. A thin scheduler shell does the
5	// GitHub I/O (search state=all, create, label, comment) and applies the verdict
6	// — the "should I file this" decision is always code here, never the shell's
7	// judgment (the same split the fleet planner uses).
8	//
9	// All behavior-defining content (agent_model, expected_outcome, agent_instructions) is read from the
10	// tracked task files, never from the issue — the body only points at the task
11	// file and carries the precondition's binding Context (DESIGN §4).
12	
13	// The labels this machinery drives. `ready-for-agent` is what the executor
14	// routine fires on; `needs-human` is the single triage state every anomaly
15	// converges to (DESIGN §4 lifecycle). Kept here as the shared source for the
16	// scheduler side; the executor reuses these plus `agent-running`.
17	export const READY_LABEL = 'ready-for-agent';
18	// A fleet-scoped task (session_scope: 'fleet') dispatches to a DISTINCT ready
19	// label so a separate, broader-scoped executor routine runs it — keeping the
20	// fleet-wide session grant off every ordinary project's self executor (the
21	// per-project-scheduling fleet/self split). Only tasks that reach other repos use
22	// this; today just growth-promote.
23	export const READY_FLEET_LABEL = 'ready-for-agent-fleet';
24	export const AGENT_RUNNING_LABEL = 'agent-running';
25	export const NEEDS_HUMAN_LABEL = 'needs-human';
26	export const WORKFLOW_FAILURE_LABEL = 'workflow-failure';
27	
28	// The ready label a task's dispatch is filed under, from its declared
29	// session_scope ('self' default → READY_LABEL; 'fleet' → READY_FLEET_LABEL). The
30	// one place this mapping lives, so the scheduler (which files) and any reader stay
31	// in sync.
32	export const readyLabelForScope = (scope) => (scope === 'fleet' ? READY_FLEET_LABEL : READY_LABEL);
33	
34	// The full label set the scheduler + executor drive, each with the colour and
35	// description a bootstrap one-off would have given it. The scheduler ENSURES every
36	// one exists (create-if-missing, idempotent) right before it dispatches — so there
37	// is no separate label-creation step to run or forget, and a deleted label
38	// self-heals on the next run. This is load-bearing, not cosmetic: GitHub does not
39	// create a label when you apply it (the issues API 422s on an unknown label), so
40	// the thing that assigns a label must guarantee it first — the
41	// gha/label-create-before-add principle, enforced in code here.
42	export const SCHEDULER_LABELS = [
43	  { name: READY_LABEL, color: '0e8a16', description: 'Claudinite scheduler: dispatch issue ready for the (self-scoped) executor to run' },
44	  { name: READY_FLEET_LABEL, color: '1d76db', description: 'Claudinite scheduler: dispatch ready for the FLEET-scoped executor (a task reaching other repos)' },
45	  { name: AGENT_RUNNING_LABEL, color: 'fbca04', description: 'Claudinite scheduler: the executor has claimed this issue and is running it' },
46	  { name: NEEDS_HUMAN_LABEL, color: 'd93f0b', description: 'Claudinite scheduler: an anomaly that converged here for human triage' },
47	  { name: WORKFLOW_FAILURE_LABEL, color: 'b60205', description: 'Claudinite scheduler: a scheduler run or task failed' },
48	];
49	
50	// The escalation code as a LABEL, so "which condition woke the agent" is countable
51	// rather than only readable. The body already names the code, but a body is prose:
52	// counting it across a fleet means fetching and parsing every dispatch issue, while a
53	// label is a search facet (`label:escalation:checks-not-green`) any repo-set query can
54	// aggregate — which is what sizing the versioned-updates pack-apply stage needs (#768,
55	// docs/versioned-updates/DESIGN.md §7).
56	//
57	// DERIVED from the code the worker fired, never a list of codes kept here: the codes
58	// live in the prework worker that raises them (a pack), the engine may not import a
59	// pack, and a hand-maintained copy of an enum on the other side of that barrier is
60	// exactly the drift the corpus forbids. So the label is minted per code, and the
61	// scheduler ensures it right before applying it — the same create-before-add
62	// discipline SCHEDULER_LABELS documents. A code that is not a plain kebab-case token
63	// gets no label (GitHub would take almost anything as a name, and a label built from
64	// a malformed code is a category nobody can query); the body still carries it.
65	export const ESCALATION_LABEL_PREFIX = 'escalation:';
66	export function escalationLabel(code) {
67	  if (typeof code !== 'string' || !/^[a-z0-9]+(-[a-z0-9]+)*$/.test(code)) return null;
68	  return {
69	    name: `${ESCALATION_LABEL_PREFIX}${code}`,
70	    color: '5319e7',
71	    description: `Claudinite scheduler: prework escalated on "${code}"`,
72	  };
73	}
74	
75	// Title: `[claudinite-task] <pack>/<task> <slot-id>` (DESIGN §4). The prefix is
76	// what keeps these issues invisible to the scheduler's own signals (self-trigger
77	// exclusion) and searchable as a family.
78	export const DISPATCH_PREFIX = '[claudinite-task]';
79	
80	export const dispatchTitle = ({ pack, task, slotId }) => `${DISPATCH_PREFIX} ${pack}/${task} ${slotId}`;
81	
82	// The (pack, task) family key — every slot's title for one task starts with
83	// `<key> ` (the trailing space before the slot id is load-bearing: it stops
84	// `foo/extract` from matching `foo/extract-more`).
85	export const dispatchTaskKey = ({ pack, task }) => `${DISPATCH_PREFIX} ${pack}/${task}`;
86	
87	// pack and task ids are single path segments (no slash, no space); the slot id
88	// is the trailing non-space token.
89	const DISPATCH_TITLE_RE = /^\[claudinite-task\]\s+([^/\s]+)\/([^/\s]+)\s+(\S+)$/;
90	
91	export function parseDispatchTitle(title) {
92	  const m = DISPATCH_TITLE_RE.exec(String(title ?? '').trim());
93	  return m ? { pack: m[1], task: m[2], slotId: m[3] } : null;
94	}
95	
96	// Is this a scheduler dispatch issue? The self-trigger exclusion the signal
97	// collectors apply so the scheduler never sees its own dispatch issues as work.
98	export const isDispatchTitle = (title) => parseDispatchTitle(title) !== null;
99	
100	// The dispatch issue body (DESIGN §4). First line is the task-file path — the
101	// only thing the executor reads to locate the worker; everything below is human
102	// framing plus the precondition's binding Context. The Context block is emitted
103	// only when the precondition produced lines (an empty scope has nothing to bind).
104	// The `### Delivered` section — what this run's prework created, by identity. It is
105	// the agent's only source for those artifacts.
106	//
107	// Absence is meaningful: no section means prework created nothing, so never write a
108	// placeholder here.
109	export function deliveredLines(delivered) {
110	  const { branch = null, pr = null, merged = false } = delivered ?? {};
111	  if (!branch && !pr) return [];
112	  return [
113	    '### Delivered by prework',
114	    'The artifacts this run created — the ones to work on.',
115	    '',
116	    ...(pr ? [`- PR: #${pr}${merged ? ' (already merged — open your own PR for further work)' : ' (open)'}`] : []),
117	    ...(branch ? [`- Branch: \`${branch}\``] : []),
118	  ];
119	}
120	
121	// The `### Why the agent is here` section — which of prework's escalation
122	// conditions fired. The worker knows it exactly; without this the agent re-derives it
123	// from the repo, and a re-derivation that disagrees with the truth is how a run ends up
124	// reporting "prework created nothing" about a cycle that just merged a PR
125	// (EdFringeAllocator#82).
126	//
127	// The condition and its counts, never the findings — those stay in the repo (DESIGN §3).
128	// Absence is meaningful here too: a worker too old to name a reason says nothing, and
129	// the agent falls back to its task file's own sweep.
130	export function escalationLines(reason) {
131	  const { code = null, detail = null } = reason ?? {};
132	  if (!code && !detail) return [];
133	  return [
134	    '### Why the agent is here',
135	    'The condition prework escalated on. Start here; the findings themselves are in the repo, not this issue.',
136	    '',
137	    `- ${detail || code}${detail && code ? ` (\`${code}\`)` : ''}`,
138	  ];
139	}
140	
141	export function dispatchBody({ taskPath, pack, task, slotId, context = [], delivered = null, reason = null }) {
142	  const lines = [taskPath, ''];
143	  if (context.length) {
144	    lines.push(
145	      `Execute the Claudinite task above (pack \`${pack}\`, task \`${task}\`, slot \`${slotId}\`).`,
146	      'The Context section below is binding scope — do not re-decide it.',
147	      '',
148	      '### Context',
149	    );
150	    for (const c of context) lines.push(`- ${c}`);
151	  } else {
152	    lines.push(`Execute the Claudinite task above (pack \`${pack}\`, task \`${task}\`, slot \`${slotId}\`).`);
153	  }
154	  // Why first, then what: the reason is what decides which of the task file's sections
155	  // the agent actually needs, and the artifacts are what it does that work on.
156	  const why = escalationLines(reason);
157	  if (why.length) lines.push('', ...why);
158	  const del = deliveredLines(delivered);
159	  if (del.length) lines.push('', ...del);
160	  return lines.join('\n') + '\n';
161	}
162	
163	// The filing decision for one due (task, slot), given `existing` — the issues
164	// the shell fetched for this task's family (title starts with the task key),
165	// each `{ number, title, state, labels }` with state 'open' | 'closed'. Two
166	// guards (DESIGN §4):
167	//   - exactly-once per (task, slot): a state=all title match for THIS slot → skip
168	//     (makes double-runs and crash-retries safe).
169	//   - at-most-one-LIVE per task: an open family issue that is still live work
170	//     suppresses a new filing → an executor outage accumulates at most one issue
171	//     per task.
172	// Otherwise: create (the shell files it labeled with `readyLabel` — the
173	// self/fleet ready label the task's scope resolves to, default `ready-for-agent`).
174	//
175	// LIVE, NOT MERELY OPEN (#821). Suppressing on any open issue read `needs-human`
176	// as live work, so an escalation did not await triage — it STOPPED the task until
177	// a person closed the issue by hand, with nothing saying the lane was shut. That
178	// made the stale-claim backstop the opposite of a backstop: it converted one
179	// session's death into a permanent stop (13 tasks across 9 repos, the oldest
180	// stopped for three weeks). A claim — `agent-running`, or a just-filed issue not
181	// yet labeled — is someone working; a terminal is nobody, and never will be.
182	//
183	// The re-filing is bounded, because a DURABLE cause escalates every slot and would
184	// otherwise accumulate one issue per slot — the spam the guard exists to prevent.
185	// One unresolved escalation is a transient session death and must not cost the
186	// task its next slot; a second says the cause outlived a full cycle of triage, so
187	// the lane holds until a person drains it. That hold is a distinct verdict
188	// (`escalated`), not the claim verdict, so "a session is on it" and "shut,
189	// pending triage" can never again look identical from outside.
190	export const NEEDS_HUMAN_HOLD = 2;
191	
192	// GitHub hands labels back as objects on the issues/search APIs and as bare
193	// strings in some fixtures; accept either.
194	const labelNames = (issue) =>
195	  (issue?.labels ?? []).map((l) => (typeof l === 'string' ? l : l?.name)).filter(Boolean);
196	
197	const isEscalated = (issue) => labelNames(issue).includes(NEEDS_HUMAN_LABEL);
198	
199	export function planDispatch({ existing = [], pack, task, slotId, readyLabel = READY_LABEL, hold = NEEDS_HUMAN_HOLD }) {
200	  const title = dispatchTitle({ pack, task, slotId });
201	  const keyPrefix = `${dispatchTaskKey({ pack, task })} `;
202	  const family = existing.filter((i) => `${(i.title ?? '').trim()} `.startsWith(keyPrefix));
203	
204	  if (family.some((i) => (i.title ?? '').trim() === title)) {
205	    return { action: 'skip', reason: `dispatch issue for slot ${slotId} already exists (exactly-once)` };
206	  }
207	  const open = family.filter((i) => i.state === 'open');
208	  const live = open.find((i) => !isEscalated(i));
209	  if (live) {
210	    return { action: 'suppress', openIssue: live.number, reason: `an open dispatch issue (#${live.number}) already covers ${pack}/${task}` };
211	  }
212	  const escalated = open.filter(isEscalated);
213	  if (escalated.length >= hold) {
214	    const numbers = escalated.map((i) => `#${i.number}`).join(', ');
215	    return {
216	      action: 'suppress', escalated: true, openIssue: escalated[0].number,
217	      reason: `${escalated.length} unresolved escalations (${numbers}) on ${pack}/${task} — held for triage, not running`,
218	    };
219	  }
220	  return { action: 'create', title, label: readyLabel, reason: `no dispatch issue yet for ${pack}/${task} slot ${slotId}` };
221	}
222	
223	// The period one slot id represents, from its leading kind char (h/d/w/m). Used
224	// only for the stale-issue backstop's threshold; daily-family slots all span a
225	// day. Monthly uses 31 days so the ~2-period threshold never fires early in a
226	// long month.
227	const SLOT_PERIOD_MS = { h: 3600e3, d: 86400e3, w: 7 * 86400e3, m: 31 * 86400e3 };
228	
229	function slotPeriodMs(slotId) {
230	  return SLOT_PERIOD_MS[String(slotId ?? '')[0]] ?? null;
231	}
232	
233	// Open dispatch issues older than `factor` of their own period (DESIGN §4: ~2
234	// periods) — the scheduler's backstop when no executor session drains them. The
235	// shell adds the escalation comment + `needs-human` to each. `issue.created_at`
236	// is the ISO string GitHub returns; a title that doesn't parse (or an unknown
237	// slot kind) is never stale here.
238	//
239	// ESCALATION IS ONCE. Escalating only adds a label and leaves the issue OPEN, so
240	// an issue that already carries `needs-human` still matches every later run —
241	// and the shell re-posts the identical comment on each. Skipping the already
242	// escalated is what makes "converge to a single visible state" true rather than
243	// a state the scheduler keeps re-announcing every hour, forever.
244	//
245	// A CLAIMED issue is not this sweep's to judge either. `agent-running` means a
246	// session engaged; whether that claim is dead is `staleClaimedDispatchIssues`'s
247	// question, and it says so in its own words. Without this the two overlap on an
248	// old claimed issue, the shell's stale-first ordering wins, and the issue is
249	// told "no executor session ran it" about a session that demonstrably ran.
250	export function staleDispatchIssues(openIssues = [], now, { factor = 2 } = {}) {
251	  const nowMs = new Date(now).getTime();
252	  return openIssues.filter((issue) => {
253	    const parsed = parseDispatchTitle(issue.title);
254	    if (!parsed) return false;
255	    const names = labelNames(issue);
256	    if (names.includes(NEEDS_HUMAN_LABEL) || names.includes(AGENT_RUNNING_LABEL)) return false;
257	    const period = slotPeriodMs(parsed.slotId);
258	    if (period === null) return false;
259	    return nowMs - new Date(issue.created_at).getTime() > factor * period;
260	  });
261	}
262	
263	// The escalation comment the shell posts on a stale dispatch issue.
264	export function staleEscalationComment(issue) {
265	  const parsed = parseDispatchTitle(issue.title);
266	  const which = parsed ? `${parsed.pack}/${parsed.task} (slot ${parsed.slotId})` : 'this task';
267	  return `This dispatch issue for ${which} has stayed open past ~2 of its scheduling periods without being executed — `
268	    + `no executor session ran it. Labeling \`${NEEDS_HUMAN_LABEL}\` for triage.`;
269	}
270	
271	// --- re-arming a lost trigger ------------------------------------------------
272	// The label event is the executor's ONLY trigger, and a delivery can be lost: the
273	// routine was down or paused, or a session died before it claimed. The issue then
274	// sits armed forever, because the label is already applied and GitHub emits
275	// `labeled` only on a fresh add. So the scheduler re-arms it — remove the ready
276	// label, add it back — which emits a new event.
277	//
278	// This is the recovery that used to live in the executor's drain sweep, then in
279	// the scheduler's hourly pass, and now runs from the daily task-janitor task —
280	// still deterministic code, still decided by the pure rules here. The sweep had EVERY triggered session also process every
281	// OTHER armed issue, so one scheduler run filing N dispatches produced N sessions
282	// each racing over the same N issues, and the claim swap could not stop it (every
283	// session read the work list before any claim landed). That is the
284	// duplicate-execution bug: the same dispatch run two or three times over,
285	// duplicate tracker issues, duplicate PRs making the same changes. Recovery
286	// belongs here, where it is a decision in code that runs once per scheduler run.
287	
288	const READY_LABELS = new Set([READY_LABEL, READY_FLEET_LABEL]);
289	
290	// The ready label an issue currently carries, or null. Re-arming reapplies THIS
291	// one, so a fleet dispatch is never re-armed as a self dispatch (which would hand
292	// it to an executor whose session lacks the cross-repo reach it needs).
293	export function readyLabelOn(issue) {
294	  return labelNames(issue).find((n) => READY_LABELS.has(n)) ?? null;
295	}
296	
297	// The open dispatch issues whose trigger evidently never landed. Re-arm only an
298	// issue that is:
299	//   - a dispatch issue (parseable title) still carrying a ready label;
300	//   - unclaimed — no `agent-running` (a live session claims before it dispatches)
301	//     and not already converged to `needs-human`;
302	//   - uncommented — the executor comments on every exit path, so a comment means
303	//     some session engaged and this is not a lost event; and
304	//   - past `graceMs` (default 20m), comfortably beyond session spin-up, so a
305	//     session already on its way is never handed a rival.
306	// A stale issue is never re-armed: it is on its way to `needs-human`, and re-arming
307	// one would loop forever. That backstop is also what bounds this — an executor that
308	// stays down is re-armed each janitor run until ~2 periods, then converges to triage.
309	// Dispatch issues left claimed by a session that died mid-run: `agent-running`
310	// with no activity for `idleMs` (~3h). Converging these used to be the executor's
311	// own step 6, which meant every concurrently-triggered session swept them and
312	// commented on the same issue — the duplicate-work bug in miniature. It is code
313	// here (run by the janitor) for the same reason the re-arm is.
314	//
315	// Scoped to `[claudinite-task]` dispatch issues deliberately (the title parse is
316	// what enforces it): a task may put `agent-running` on an issue IT owns — a
317	// request its pipeline has claimed, which stays claimed while its PR is in review,
318	// far longer than 3h — and only that task knows when its own claim is stale.
319	export function staleClaimedDispatchIssues(openIssues = [], now, { idleMs = 3 * 3600e3 } = {}) {
320	  const nowMs = new Date(now).getTime();
321	  return openIssues.filter((issue) => {
322	    if (!parseDispatchTitle(issue.title)) return false;
323	    const names = labelNames(issue);
324	    if (!names.includes(AGENT_RUNNING_LABEL) || names.includes(NEEDS_HUMAN_LABEL)) return false;
325	    return nowMs - new Date(issue.updated_at ?? issue.created_at).getTime() > idleMs;
326	  });
327	}
328	
329	// The comment the shell posts when it reclaims a dead session's claim.
330	export function staleClaimComment(issue) {
331	  const parsed = parseDispatchTitle(issue.title);
332	  const which = parsed ? `${parsed.pack}/${parsed.task} (slot ${parsed.slotId})` : 'this task';
333	  return `This dispatch issue for ${which} has carried \`${AGENT_RUNNING_LABEL}\` for over 3h with no activity — `
334	    + `the executor session that claimed it never converged it. Labeling \`${NEEDS_HUMAN_LABEL}\` for triage.`;
335	}
336	
337	export function rearmDispatchIssues(openIssues = [], now, { graceMs = 20 * 60e3 } = {}) {
338	  const nowMs = new Date(now).getTime();
339	  const stale = new Set(staleDispatchIssues(openIssues, now).map((i) => i.number));
340	  return openIssues.filter((issue) => {
341	    if (!parseDispatchTitle(issue.title)) return false;
342	    if (stale.has(issue.number)) return false;
343	    if (!readyLabelOn(issue)) return false;
344	    const names = labelNames(issue);
345	    if (names.includes(AGENT_RUNNING_LABEL) || names.includes(NEEDS_HUMAN_LABEL)) return false;
346	    if ((issue.comments ?? 0) > 0) return false;
347	    return nowMs - new Date(issue.created_at).getTime() > graceMs;
348	  });
349	}
