84	  }
85	  if (!MODEL_FAMILIES.includes(decl.agent_model)) {
86	    bad(`"agent_model" ${JSON.stringify(decl.agent_model)} is not a legal model family`, `set one of: ${MODEL_FAMILIES.join(', ')}`);
87	  }
