89	    bad(`"expected_outcome" ${JSON.stringify(decl.expected_outcome)} is not a legal outcome ceiling`, `set one of: ${OUTCOMES.join(', ')}`);
90	  }
91	  // agent_instructions — REQUIRED for an agentic task (agent_model !== 'none'):
92	  // that's the worker file the agent reads. A `none` task runs no agent, so the
93	  // field is not applicable and is neither required nor validated when present.
94	  if (decl.agent_model !== 'none' && (typeof decl.agent_instructions !== 'string' || decl.agent_instructions.trim() === '')) {
95	    bad('an agentic task (agent_model !== "none") declares no string "agent_instructions"', 'point "agent_instructions" at the worker file beside task.mjs (e.g. "task.md")');
96	  }
