1	// Due-slot math for the vendored hourly scheduler (per-project-scheduling
2	// DESIGN §3). Pure and stateless: given the repo's `schedule` anchor, the
3	// frequencies its tasks declare, the current time `now`, and the timestamp
4	// `lastSuccess` of the scheduler's last SUCCESSFUL run (read from the Actions
5	// run ledger GitHub already keeps — there is no watermark file to corrupt),
6	// this decides exactly which frequencies are due and the slot id each is
7	// running under.
8	//
9	// The whole model is: consider ONLY the single most-recent scheduled slot per
10	// frequency, and it is due iff its time falls in `(lastSuccess, now]`.
11	//   - Miss / outage self-heals — the next successful run catches up the one
12	//     most-recent daily/weekly/monthly slot; a 3-day outage yields one catch-up
13	//     evaluation per frequency, never a backfill storm (DESIGN §3.1).
14	//   - HOURLY never catches up for free: its most-recent slot is always the
15	//     current hour, so an outage evaluates the current poll once and never a
16	//     stale one — no special case needed, the most-recent-only rule delivers it.
17	//   - Late / early fire is irrelevant: due-ness is schedule math, never
18	//     wall-clock equality with the (hashed :10–:50) cron minute.
19	//   - First run (`lastSuccess` null / fresh adoption) → the most-recent slot of
20	//     the FIRST-RUN SET only (hourly + the daily family): the immediate
21	//     evaluation that smoke-tests a newly-wired repo, without an off-anchor
22	//     weekly/monthly run on it (DESIGN §3.1, #522).
23	//
24	// `lastSuccess` null means exactly one thing — the ledger was read and holds no
25	// successful run. A ledger that could not be READ is never null: the caller
26	// (`lastSuccessTime`) throws, and the run fails rather than reach this math with
27	// a watermark it had to guess (#522).
28	//
29	// All times are UTC (the `schedule` values are UTC by contract, DESIGN §2). This
30	// module never reads the clock itself — `now` is always injected — so the whole
31	// due-ness decision is deterministic and testable.
32	
33	// The legal frequency tokens (DESIGN §1). `task-declaration-shape` is what
34	// rejects anything outside this set at author time; here an unknown token is
35	// simply never due (defensive — the scheduler must not throw on a stray value).
36	//
37	// `manual` is the one non-cadence: a manual task is NEVER due on any schedule and
38	// runs only when a hand-started run forces it (`FORCE_TASKS`, run.mjs). It exists
39	// for operator levers — work that answers no recurring question but wants a task's
40	// whole apparatus (declaration, contract validation, prework, the dispatch issue)
41	// when a human pulls it. dueSlots skips it unconditionally; mostRecentSlot still
42	// resolves it, because a forced run needs a slot to run under.
43	export const FREQUENCIES = ['hourly', 'daily-2h', 'daily-1h', 'daily', 'daily+1h', 'weekly', 'monthly', 'manual'];
44	
45	// What a FIRST run (an empty ledger — fresh adoption) evaluates. Deliberately
46	// not every frequency: the first run is an adoption smoke test, and the wiring
47	// it proves — task discovery, signal collection, the dispatch issue, the label,
48	// executor pickup — is identical whatever the frequency, so the daily family
49	// exercises all of it. Including weekly and monthly would only add an
50	// off-anchor run of their unconditional tasks (open-web research, pack
51	// discovery, the fleet sweep) on the least-proven repo in the fleet, at the
52	// moment nobody is watching it. They wait for their real anchor, which is due
53	// normally once the ledger has this run in it (#522).
54	export const FIRST_RUN_FREQUENCIES = ['hourly', 'daily-2h', 'daily-1h', 'daily', 'daily+1h'];
55	
56	// The documented anchor defaults (DESIGN §2) — applied when a repo omits
57	// `schedule` or any of its keys. This is the single source of these values; the
58	// checks layer's load-time range validation (engine/checks/helpers/repo-context.mjs)
59	// only bounds them, it does not re-declare them.
60	export const DEFAULT_SCHEDULE = { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 };
61	
62	// Sun-indexed to match Date#getUTCDay (0 = Sunday). Also the canonical weekday
63	// vocabulary the config validator mirrors.
64	export const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
65	
66	// Hours the daily family offsets the anchor hour by (DESIGN §2).
67	const DAILY_OFFSETS = { 'daily-2h': -2, 'daily-1h': -1, daily: 0, 'daily+1h': 1 };
68	
69	const HOUR_MS = 3600 * 1000;
70	const DAY_MS = 24 * HOUR_MS;
71	const pad = (n) => String(n).padStart(2, '0');
72	const ymd = (d) => `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
73	
74	// Last calendar day of a UTC month (day 0 of the next month rolls back).
75	const daysInMonth = (year, monthIndex) => new Date(Date.UTC(year, monthIndex + 1, 0)).getUTCDate();
76	
77	// Fill any absent key with its documented default; leave present values
78	// untouched (the checks layer has already range-validated them at load).
79	export function normalizeSchedule(schedule = {}) {
80	  const s = schedule || {};
81	  return {
82	    dailyHour: Number.isInteger(s.dailyHour) ? s.dailyHour : DEFAULT_SCHEDULE.dailyHour,
83	    weeklyDay: WEEKDAYS.includes(s.weeklyDay) ? s.weeklyDay : DEFAULT_SCHEDULE.weeklyDay,
84	    monthlyDay: Number.isInteger(s.monthlyDay) ? s.monthlyDay : DEFAULT_SCHEDULE.monthlyDay,
85	  };
86	}
87	
88	// The most-recent scheduled slot for one frequency at time `now`:
89	// `{ time: Date, id: string }` where `time` is the slot's UTC instant (≤ now)
90	// and `id` is the dispatch-issue slot id (DESIGN §4). `schedule` is assumed
91	// already normalized. `now` may be a Date or anything the Date ctor accepts.
92	export function mostRecentSlot(frequency, schedule, now) {
93	  const s = normalizeSchedule(schedule);
94	  now = new Date(now);
95	  const nowMs = now.getTime();
96	
97	  if (frequency === 'manual') {
98	    // A manual task has no scheduled instant — its "slot" exists only so a FORCED
99	    // run has something to run under. The id is the anchor date alone; uniqueness
100	    // across same-day forces comes from the `~f<runId>` marker planRun appends to
101	    // every forced slot id, not from here.
102	    const time = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
103	    return { time, id: `x${ymd(time)}` };
104	  }
105	
106	  if (frequency === 'hourly') {
107	    // The top of the current hour — the poll never backfills a past hour.
108	    const time = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), now.getUTCHours()));
109	    return { time, id: `h${ymd(time)}T${pad(time.getUTCHours())}Z` };
110	  }
111	
112	  if (frequency in DAILY_OFFSETS) {
113	    const off = DAILY_OFFSETS[frequency];
114	    // Walk anchor DATES back from today until the slot instant is ≤ now. The id
115	    // keeps the ANCHOR date, so a `daily-2h` with dailyHour < 2 whose instant
116	    // lands on the previous calendar day still carries the anchor's date — the
117	    // wrap behavior of DESIGN §2 falls out for free.
118	    let anchor = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
119	    for (;;) {
120	      const time = new Date(anchor.getTime() + (s.dailyHour + off) * HOUR_MS);
121	      if (time.getTime() <= nowMs) return { time, id: `d${ymd(anchor)}` };
122	      anchor = new Date(anchor.getTime() - DAY_MS);
123	    }
124	  }
125	
126	  if (frequency === 'weekly') {
127	    const targetDow = WEEKDAYS.indexOf(s.weeklyDay);
128	    let date = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
129	    // Up to 8 steps guarantees the previous week's slot even when today is the
130	    // weekly day but earlier than dailyHour.
131	    for (let i = 0; i < 8; i += 1) {
132	      if (date.getUTCDay() === targetDow) {
133	        const time = new Date(date.getTime() + s.dailyHour * HOUR_MS);
134	        if (time.getTime() <= nowMs) return { time, id: `w${ymd(date)}` };
135	      }
136	      date = new Date(date.getTime() - DAY_MS);
137	    }
138	    // Unreachable in practice (a matching weekday always exists within 7 days).
139	    throw new Error(`no weekly slot resolved for ${s.weeklyDay}`);
140	  }
141	
142	  if (frequency === 'monthly') {
143	    let year = now.getUTCFullYear();
144	    let month = now.getUTCMonth();
145	    for (;;) {
146	      const day = Math.min(s.monthlyDay, daysInMonth(year, month)); // clamp to month length (DESIGN §2)
147	      const time = new Date(Date.UTC(year, month, day) + s.dailyHour * HOUR_MS);
148	      if (time.getTime() <= nowMs) return { time, id: `m${year}-${pad(month + 1)}` };
149	      month -= 1;
150	      if (month < 0) { month = 11; year -= 1; }
151	    }
152	  }
153	
154	  throw new Error(`unknown frequency "${frequency}"`);
155	}
156	
157	// The frequencies that are due right now, each with its slot id/time. `lastSuccess`
158	// is the last successful scheduler run's timestamp (Date / ISO string / null);
159	// null means "the ledger holds no prior success" → the FIRST_RUN_FREQUENCIES set
