161	export function dueSlots(frequencies, schedule, now, lastSuccess) {
162	  const s = normalizeSchedule(schedule);
163	  now = new Date(now);
164	  const nowMs = now.getTime();
165	  const tMs = lastSuccess === null || lastSuccess === undefined ? null : new Date(lastSuccess).getTime();
166	
