168	  for (const frequency of frequencies) {
169	    if (!FREQUENCIES.includes(frequency)) continue;
170	    if (frequency === 'manual') continue; // never due on any cadence — forced runs only (run.mjs)
171	    const slot = mostRecentSlot(frequency, s, now);
172	    const t = slot.time.getTime();
173	    // `t <= nowMs` holds by construction; kept explicit as the stated contract.
174	    const due = tMs === null
175	      ? FIRST_RUN_FREQUENCIES.includes(frequency) && t <= nowMs
176	      : t > tMs && t <= nowMs;
