1	// Fresh-path wiring convergence (task-prework DESIGN §7, the primitive
2	// absorbed from #405). The deterministic half of the self-refresh that
3	// has nothing to do with the vendored mount's CONTENT: the repo-specific wiring a
4	// scheduled Claudinite consumer must carry, converged idempotently in code so the
5	// nightly refresh never needs a model to re-enact bootstrap's prose.
6	//
7	// One source of truth: bootstrap Part 5 (the settings hooks) + Part 6 (the
8	// scheduler workflow) describe this same set for a fresh adoption; this module is
9	// what both bootstrap and the update flows CALL, so the wiring can never drift between
10	// "how a repo is set up" and "how the nightly keeps it set up".
11	//
12	// Operates on a repo working tree at `root` with node:fs directly (like
13	// apply-vendor-set.mjs), returning a summary of what it changed — idempotent: a
14	// repo already converged produces an empty change list.
15	
16	import { existsSync, readFileSync, writeFileSync, mkdirSync } from 'node:fs';
17	import { join, dirname, relative } from 'node:path';
18	import { pathToFileURL } from 'node:url';
19	import { hashedCron } from './hash-minute.mjs';
20	import { writeRulesIndex, RULES_INDEX_FILE, RULES_INDEX_IMPORT } from '../pack_loader/generate-rules-index.mjs';
21	import { LOCAL_PACKS_SUBDIR, LOCAL_DECL_PREFIX } from '../pack_loader/pack-registry.mjs';
22	
23	// The settings-hook registrations a scheduled repo carries (bootstrap Part 5).
24	// Ensured present without clobbering — a set-union keyed on the command string, so
25	// a repo's own extra hooks and any hand-added entries survive untouched.
26	export const REQUIRED_HOOKS = [
27	  { event: 'SessionStart', matcher: null, command: 'bash $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/session-start-command.sh' },
28	  { event: 'Stop', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/stop-command.mjs' },
29	  { event: 'PreToolUse', matcher: 'Bash', command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/pretooluse-command.mjs' },
30	  { event: 'SessionEnd', matcher: null, command: 'node $CLAUDE_PROJECT_DIR/.claudinite/shared/engine/hooks/session-end-command.mjs' },
31	];
32	
33	export const SCHEDULER_WORKFLOW = '.github/workflows/claudinite-scheduler.yml';
34	export const SETTINGS_PATH = '.claude/settings.json';
35	export const CLAUDE_MD = 'CLAUDE.md';
36	export const README = 'README.md';
37	
38	// The pack-badge row: the marks of the packs this repo declares, on a single
39	// line of its README. Adoption seeds it and the repo owns it from there — which
40	// is why the row is gated behind `{ badges: true }` (the CLI's `--badges`, passed
41	// by bootstrap alone) rather than converged like the surfaces around it. A
42	// README belongs to its repo: a nightly that re-derived this row would rewrite a
43	// member's README every time its declaration moved, so the nightly stays out and
44	// a stale row is the repo's to fix (re-run the converge with `--badges`).
45	//
46	// Delimited by HTML comments rather than located by position, so the row can be
47	// re-converged in place wherever the repo has moved it, and so anything the repo
48	// writes AFTER the closing marker on the same line (a tagline, a build badge) is
49	// its own and survives untouched — which is why the CLOSING marker stays inline,
50	// at the end of the badges' own line.
51	//
52	// The OPENING marker gets a line to itself, and that newline is load-bearing: a
53	// line that BEGINS with `<!--` opens a CommonMark HTML block, and every character
54	// through the line carrying `-->` is then emitted as raw HTML. Put the badges
55	// after the opening marker on one line and a README renders the literal text
56	// `![basics](…)` instead of the images (#587). Breaking the line ends the HTML
57	// block at the marker, so the badges start a paragraph and parse as markdown.
58	export const BADGE_ROW_START = '<!-- claudinite:packs -->';
59	export const BADGE_ROW_END = '<!-- /claudinite:packs -->';
60	const BADGE_ROW_RE = new RegExp(`${BADGE_ROW_START}[\\s\\S]*?${BADGE_ROW_END}`);
61	
62	// The retired corpus-index import (#385): a line importing `.claudinite/shared/CLAUDE.md`.
63	// The whole line (and its trailing newline) is removed wherever it appears.
64	const CORPUS_IMPORT_RE = /^.*@\.claudinite\/shared\/CLAUDE\.md.*\n?/m;
65	
66	// The project's settings, loaded through the one reader that validates them.
67	// Dynamic and in one place: the scheduler reaches the checks helpers exactly here,
68	// so the cross-tree import stays a single, reviewable edge.
69	const repoConfig = async (root) => (await import('../checks/helpers/repo-context.mjs')).loadConfig(root);
70	
71	// The repo Actions secrets its scheduled tasks declare via `required_secrets`,
72	// deduped and sorted. Async because task discovery is; pure otherwise.
73	export async function declaredSecrets(root, config) {
74	  const { discoverTasks } = await import('./discover.mjs');
75	  const { tasks } = await discoverTasks(root, config);
76	  return [...new Set(tasks.flatMap((t) => t.decl?.required_secrets ?? []))].sort();
77	}
78	
79	// Stamp the declared secrets into the scheduler workflow's engine step, beside
80	// GITHUB_TOKEN. This is the whole delivery mechanism: GitHub Actions requires each
81	// secret to be named statically in the workflow, and a task's `required_secrets` is
82	// exactly that list — so the wiring converge writes it, and a worker then reads
83	// `process.env.<NAME>` like any other environment variable. No bundle, no parsing,
84	// no engine-side selection. Regenerated from the stub each converge, so the list
85	// tracks the declarations rather than accumulating.
86	export function withDeclaredSecrets(stubText, names = []) {
87	  if (!names.length) return stubText;
88	  const lines = names.map((n) => `          ${n}: \${{ secrets.${n} }}`).join('\n');
89	  return stubText.replace(/^(\s*GITHUB_TOKEN: \$\{\{ github\.token \}\})$/m, `$1\n${lines}`);
90	}
91	
92	// Re-converge the scheduler workflow to the vendored stub, with the cron minute set
93	// to this repo's stable hashed value (never guessed — hash-minute.mjs, a pure
94	// function of the full name, so re-vendors and this convergence agree) and the
95	// declared `required_secrets` stamped into the engine step's env. `stubText` is the
96	// vendored stub's content (the caller reads it from the mount). Returns true when
97	// the file was written (absent, or drifted from the target).
98	// What this repo's scheduler workflow SHOULD contain — the stub with its secrets
99	// stamped and its cron resolved, as text, touching no disk.
100	//
101	// Split out from the converge below because the pack update flow needs the answer
102	// without the side effect: it cannot write this file (its caller pushes with the
103	// Action's GITHUB_TOKEN, which GitHub never lets near `.github/workflows/`), so it
104	// WITHHOLDS the content and hands it to a lane that can. A flow that had to write
105	// the file in order to learn what it should say could not do that.
106	export function schedulerWorkflowTarget(fullName, stubText, secretNames = []) {
107	  return withDeclaredSecrets(stubText, secretNames)
108	    .replace(/cron:\s*'[^']*'/, `cron: '${hashedCron(fullName)}'`);
109	}
110	
111	export function convergeSchedulerWorkflow(root, fullName, stubText, secretNames = []) {
112	  const target = schedulerWorkflowTarget(fullName, stubText, secretNames);
113	  const path = join(root, SCHEDULER_WORKFLOW);
114	  const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
115	  if (current === target) return false;
116	  mkdirSync(dirname(path), { recursive: true });
117	  writeFileSync(path, target);
118	  return true;
119	}
120	
121	// Ensure the required settings hooks are present (add-if-missing, never clobber).
122	// Returns { added: [labels], error? }. A malformed settings file is reported, never
123	// overwritten (the transactional stance — surface it, don't destroy hand config).
124	export function ensureHooks(root) {
125	  const path = join(root, SETTINGS_PATH);
126	  let settings = {};
127	  if (existsSync(path)) {
128	    try { settings = JSON.parse(readFileSync(path, 'utf8')); }
129	    catch { return { added: [], error: `${SETTINGS_PATH} is not valid JSON — left untouched` }; }
130	  }
131	  settings.hooks ??= {};
132	  const added = [];
133	  for (const h of REQUIRED_HOOKS) {
134	    const list = (settings.hooks[h.event] ??= []);
135	    const present = list.some((group) =>
136	      (h.matcher == null || group.matcher === h.matcher)
137	      && (group.hooks ?? []).some((entry) => entry?.command === h.command));
138	    if (!present) {
139	      list.push({ ...(h.matcher != null ? { matcher: h.matcher } : {}), hooks: [{ type: 'command', command: h.command }] });
140	      added.push(`${h.event}${h.matcher ? `[${h.matcher}]` : ''}`);
141	    }
142	  }
143	  if (added.length) {
144	    mkdirSync(dirname(path), { recursive: true });
145	    writeFileSync(path, JSON.stringify(settings, null, 2) + '\n');
146	  }
147	  return { added };
148	}
149	
150	// Remove the retired `@.claudinite/shared/CLAUDE.md` corpus-index import (#385) from
151	// the repo's CLAUDE.md. Returns true when a line was removed.
152	export function removeRetiredCorpusImport(root) {
153	  const path = join(root, CLAUDE_MD);
154	  if (!existsSync(path)) return false;
155	  const text = readFileSync(path, 'utf8');
156	  if (!CORPUS_IMPORT_RE.test(text)) return false;
157	  writeFileSync(path, text.replace(CORPUS_IMPORT_RE, ''));
158	  return true;
159	}
160	
161	// The CLAUDE.md channel (#807): the generated rules index, plus the one line in the
162	// repo's own CLAUDE.md that imports it. Converged here rather than left to a session
163	// because the index is a function of the DECLARATION — so the two flows that already
164	// change a declaration (the nightly engine refresh and any pack change) are exactly
165	// the moments it can go stale, and both call convergeWiring.
166	//
167	// NOT the retired `@.claudinite/shared/CLAUDE.md` this file still strips above. That
168	// import reached INTO the mount, which is one-directional and slated to become a
169	// submodule; this one names a consumer-owned file sitting BESIDE it, derived from the
170	// consumer's own declaration. The two coexist deliberately: a member converging today
171	// loses the old shape and gains the new one in the same pass.
172	//
173	// The import goes after the first `# ` heading when the repo has one (the badge row's
174	// placement rule, for the same reason — a repo's title stays its first line), and at
175	// the very top otherwise. A repo with no CLAUDE.md at all gets one: without it the
176	// index is a file nothing loads.
177	const RULES_INDEX_IMPORT_RE = new RegExp(`^\\s*${RULES_INDEX_IMPORT.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*$`, 'm');
178	
179	export function ensureRulesIndexImport(root) {
180	  const path = join(root, CLAUDE_MD);
181	  if (!existsSync(path)) {
182	    writeFileSync(path, `${RULES_INDEX_IMPORT}\n`);
183	    return true;
184	  }
185	  const text = readFileSync(path, 'utf8');
186	  if (RULES_INDEX_IMPORT_RE.test(text)) return false;
187	  const lines = text.split('\n');
188	  const title = lines.findIndex((l) => l.startsWith('# '));
189	  const at = title === -1 ? 0 : title + 1;
190	  lines.splice(at, 0, ...(at === 0 ? [RULES_INDEX_IMPORT, ''] : ['', RULES_INDEX_IMPORT]));
191	  writeFileSync(path, lines.join('\n'));
192	  return true;
193	}
194	
195	// A GENERATED file wants a `merge=ours` .gitattributes entry (the canon's
196	// GENERATED-file discipline and the `generated-merge-driver` check that enforces it),
197	// declared in the same converge that first writes the file — otherwise every member
198	// picks up an advisory finding on a file it did not author.
199	export const RULES_INDEX_MERGE_ATTR = 'claudinite-rules.GENERATED.md merge=ours';
200	
201	export function ensureRulesIndexMergeAttribute(root) {
202	  const path = join(root, '.gitattributes');
203	  const text = existsSync(path) ? readFileSync(path, 'utf8') : '';
204	  if (text.split('\n').some((l) => l.trim() === RULES_INDEX_MERGE_ATTR)) return false;
205	  writeFileSync(path, (text && !text.endsWith('\n') ? `${text}\n` : text) + `${RULES_INDEX_MERGE_ATTR}\n`);
206	  return true;
207	}
208	
209	// --- the repo's own local pack, seeded once at adoption ----------------------
210	
211	// Every repo has lessons that are its own and portable nowhere: they need a home the
212	// moment there is anything to write, and a session that has to invent one first
213	// usually doesn't — it writes the rule into `basics` or into a `CLAUDE.md` paragraph
214	// instead, which is how a project's rules end up somewhere the corpus cannot reach.
215	// So adoption seeds the home empty, named for the repo, declared and imported like any
216	// other pack.
217	//
218	// BOOTSTRAP ONLY, and gated like the badge row for the same reason: this is a one-time
219	// seed of a file the repo then OWNS. A nightly that re-created it would resurrect a
220	// pack the owner deliberately deleted, and a nightly that rewrote it would overwrite
221	// the rules it exists to hold.
222	
223	// A repo name as a pack id: kebab-case, the canon's naming rule for a pack directory
224	// (lowercase words joined by single hyphens), since the id is what the declaration,
225	// the mount path and every cross-reference then spell.
226	export const packIdForRepo = (fullName) => (fullName ?? '').split('/').pop()
227	  .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
228	  .replace(/[^a-zA-Z0-9]+/g, '-')
229	  .toLowerCase()
230	  .replace(/^-+|-+$/g, '');
231	
232	const SEED_MANIFEST = (id) => `// ${id} — this repo's own rules: the ones that are true here and portable nowhere.
233	// Seeded empty at adoption; everything in it is this repo's to write. A lesson that
234	// would hold in another repo belongs in a canon pack instead — propose it upstream.
235	export default {
236	  id: '${id}',
237	  version: 1,
238	  ruleRoutingGuidance: {
239	    belongs: 'working rules and lessons specific to this repository and not portable to any other',
240	    excludes: 'anything true beyond this repo — that belongs in a canon pack, proposed upstream',
241	  },
242	  detect: null,
243	  marker: null,
244	  prose: 'RULES.md',
245	  worldRules: [],
246	};
247	`;
248	
249	const SEED_PROSE = (id) => `# ${id} — this repo's own rules
250	
251	The capture surface for lessons **specific to this repository**. Loaded into every session
252	through the rules index, so what lands here should be a directive an agent can act on, not a
253	description of how something works.
254	
255	A lesson that would hold in another repo does not belong here — propose it to the Claudinite
256	canon instead, where every repo gets it.
257	
258	<!-- Nothing yet. The growth lifecycle writes here; so may you. -->
259	`;
260	
261	// Seed `.claudinite/local/packs/<repo>/` and declare it. Returns the pack id when it
262	// created one, null when the repo already has that pack or already declares any local
263	// pack — a repo that has grown its own home must never get a second, empty one.
264	export function seedRepoLocalPack(root, fullName) {
265	  const id = packIdForRepo(fullName);
266	  if (!id) return null;
267	  const dir = join(root, LOCAL_PACKS_SUBDIR, id);
268	  if (existsSync(dir)) return null;
269	
270	  const settingsPath = join(root, '.claudinite-checks.json');
271	  let raw;
272	  try { raw = JSON.parse(readFileSync(settingsPath, 'utf8')); } catch { return null; }
273	  const declared = Array.isArray(raw.packs) ? raw.packs : [];
274	  // Any local declaration at all means this repo already has a home of its own.
275	  if (declared.some((p) => String(typeof p === 'string' ? p : p?.id).startsWith('local'))) return null;
276	
277	  mkdirSync(dir, { recursive: true });
278	  writeFileSync(join(dir, 'pack.mjs'), SEED_MANIFEST(id));
279	  writeFileSync(join(dir, 'RULES.md'), SEED_PROSE(id));
280	
281	  // Declared as text, never a JSON round-trip: re-serializing rewrites what it was not
282	  // asked to — `ensure_ascii` escapes every non-ASCII character in a settings file full
283	  // of prose, and indent and key order become the serializer's opinion.
284	  const text = readFileSync(settingsPath, 'utf8');
285	  const entry = `"${LOCAL_DECL_PREFIX}${id}"`;
286	  const patched = text.replace(/("packs"\s*:\s*\[)/, (m) => `${m}\n    ${entry},`);
287	  writeFileSync(settingsPath, patched === text
288	    ? text // no `packs` array to extend — leave the file alone rather than guess at its shape
289	    : patched);
290	  return id;
291	}
292	
293	// Strip the retired `badges` setting from `.claudinite-checks.json`. `badges` is
294	// not in CONFIG_KEYS, so a member still carrying it gets an unknown-setting error
295	// until the key goes; doing it here — beside the retired corpus import, for the
296	// same reason — means the converge that already runs on every member clears it,
297	// and nobody hand-edits a settings file to satisfy a check.
298	// Returns true when the key was removed. A malformed settings file is left alone.
299	//
300	// Cut out as TEXT, re-serializing only as a fallback: a JSON round-trip rewrites
301	// the whole file — re-escaping every non-ASCII character in the prose a settings
302	// file is full of — so a three-line deletion arrives as a diff touching every
303	// `reason` in the repo.
304	export function removeRetiredBadgeSetting(root) {
305	  const path = join(root, '.claudinite-checks.json');
306	  if (!existsSync(path)) return false;
307	  const text = readFileSync(path, 'utf8');
308	  let raw;
309	  try { raw = JSON.parse(text); } catch { return false; }
310	  if (raw === null || typeof raw !== 'object' || Array.isArray(raw) || raw.badges === undefined) return false;
311	  // The key as a materialized settings file carries it: two-space indent, either
312	  // followed by a comma (mid-object) or preceded by one (last key).
313	  const surgical = text.replace(/(,)?\n[ \t]*"badges"[ \t]*:[ \t]*\{[^{}]*\}(,)?(?=\n)/, (m, before, after) => (before && after ? ',' : ''));
314	  const next = surgical !== text && parses(surgical, raw) ? surgical
315	    : JSON.stringify(rest(raw), null, 2) + '\n';
316	  writeFileSync(path, next);
317	  return true;
318	}
319	
320	const rest = ({ badges, ...keep }) => keep;
321	// The surgical cut is only taken when it produces the settings the round-trip would
322	// have — never trust a regex against JSON without re-reading what it made.
323	const parses = (text, raw) => {
324	  try { return JSON.stringify(JSON.parse(text)) === JSON.stringify(rest(raw)); }
325	  catch { return false; }
326	};
327	
328	// The row's entries: each declared pack (the `requires` closure included, in
329	// declaration order) that has a badge on disk, as { id, path } with the path
330	// relative to the repo root. Derived from the pack's own `dir`, so it resolves to
331	// `packs/<id>/…` in the canon home and `.claudinite/shared/packs/<id>/…` in a
332	// consumer with no branch on which repo this is. A pack whose badge is missing is
333	// skipped rather than reported: a repo's own local pack need not have one.
334	export async function badgeRowEntries(root, config) {
335	  const { loadPacks, resolveDeclaredPacks, packEntryId } = await import('../pack_loader/pack-registry.mjs');
336	  const packs = await loadPacks({ localRoot: root });
337	  const byId = new Map(packs.map((p) => [p.id, p]));
338	  const entries = [];
339	  for (const entry of resolveDeclaredPacks(config.packs ?? [], packs)) {
340	    const pack = byId.get(packEntryId(entry));
341	    if (!pack || typeof pack.badge !== 'string' || !pack.badge) continue;
342	    const path = relative(root, join(pack.dir, pack.badge)).split('\\').join('/');
343	    if (existsSync(join(root, path))) entries.push({ id: pack.id, path });
344	  }
345	  return entries;
346	}
347	
348	export const renderBadgeRow = (entries) =>
349	  `${BADGE_ROW_START}\n${entries.map((e) => `![${e.id}](${e.path} "${e.id}")`).join(' ')}${BADGE_ROW_END}`;
350	
351	// Write the row into the repo's README: replacing the delimited block where one
352	// exists, otherwise introducing it just under the title (a README's badges belong
353	// where a reader looks first) or at the very top when there is no heading.
354	// Returns true when the file was written. No README, or nothing to show, means
355	// nothing to do — this converge never creates a README.
356	export function convergeBadgeRow(root, entries) {
357	  const path = join(root, README);
358	  if (!existsSync(path) || !entries.length) return false;
359	  const text = readFileSync(path, 'utf8');
360	  const row = renderBadgeRow(entries);
361	  if (BADGE_ROW_RE.test(text)) {
362	    const next = text.replace(BADGE_ROW_RE, row);
363	    if (next === text) return false;
364	    writeFileSync(path, next);
365	    return true;
366	  }
367	  const lines = text.split('\n');
368	  const title = lines.findIndex((l) => l.startsWith('# '));
369	  const at = title === -1 ? 0 : title + 1;
370	  lines.splice(at, 0, ...(at === 0 ? [row, ''] : ['', row]));
371	  writeFileSync(path, lines.join('\n'));
372	  return true;
373	}
374	
375	// Converge every wiring surface, returning a flat summary of what changed (empty
376	// when the repo was already converged). `stubText` is the vendored scheduler stub.
377	//
378	// `badges` defaults off, and that default is the point: the nightly takes this
379	// call as it stands and only bootstrap opts the README row in.
380	// `workflows: false` converges everything EXCEPT `.github/workflows/`. The engine
381	// update flow passes it: the scheduler workflow's content is a function of the
382	// task set, so pack changes are what rewrite it, and only the pack flow carries a
383	// credential that can land a workflow file at all (DESIGN §2.4, §3.7). A flow that
384	// wrote one it cannot deliver would fail its whole push, not just that file.
385	// `seedLocalPack` defaults off for the same reason `badges` does: both are one-time
386	// seeds of files the repo then owns, and only bootstrap passes them.
387	export async function convergeWiring(root, fullName, stubText, secretNames = [], { badges = false, workflows = true, seedLocalPack = false } = {}) {
388	  const changed = [];
389	  if (workflows && convergeSchedulerWorkflow(root, fullName, stubText, secretNames)) changed.push(SCHEDULER_WORKFLOW);
390	  const hooks = ensureHooks(root);
391	  for (const h of hooks.added) changed.push(`hook:${h}`);
392	  if (removeRetiredCorpusImport(root)) changed.push(`removed retired ${CLAUDE_MD} corpus import`);
393	  if (removeRetiredBadgeSetting(root)) changed.push('removed retired badges setting');
394	  // Adoption only, and BEFORE the index: seeding declares a pack, and the index is a
395	  // function of the declaration, so seeding after it would leave the repo's own pack
396	  // unimported until some later converge.
397	  if (seedLocalPack) {
398	    const seeded = seedRepoLocalPack(root, fullName);
399	    if (seeded) changed.push(`seeded ${LOCAL_PACKS_SUBDIR}/${seeded}`);
400	  }
401	  // The CLAUDE.md channel, in dependency order: the index, then the import that
402	  // loads it, then the merge attribute that keeps it from being hand-resolved.
403	  if (await writeRulesIndex(root)) changed.push(RULES_INDEX_FILE);
404	  if (ensureRulesIndexImport(root)) changed.push(`${CLAUDE_MD} rules-index import`);
405	  if (ensureRulesIndexMergeAttribute(root)) changed.push('.gitattributes merge=ours for the rules index');
406	  if (badges && convergeBadgeRow(root, await badgeRowEntries(root, await repoConfig(root)))) changed.push(`${README} pack row`);
407	  return { changed, ...(hooks.error ? { error: hooks.error } : {}) };
408	}
409	
410	// CLI: `node converge-wiring.mjs [owner/repo] [--badges] [--seed-local-pack]` —
411	// converge THIS repo's wiring. The full name comes from argv or
412	// GITHUB_REPOSITORY/CLAUDINITE_REPO; the scheduler stub from the vendored mount. This
413	// is the single surface bootstrap (Part 6) and the update flows both invoke, so the
414	// wiring set is defined once, here — and the two flags are the whole difference
415	// between them. Both are ONE-TIME SEEDS of files the repo then owns (the README badge
416	// row, the repo's own local pack), which is exactly why the nightly must not pass
417	// them: it would rewrite a row the owner moved, or resurrect a pack they deleted.
418	async function main() {
419	  const argv = process.argv.slice(2);
420	  const badges = argv.includes('--badges');
421	  const seedLocalPack = argv.includes('--seed-local-pack');
422	  const fullName = argv.find((a) => !a.startsWith('--')) || process.env.GITHUB_REPOSITORY || process.env.CLAUDINITE_REPO;
423	  if (!fullName) { console.error('converge-wiring: need owner/repo (argv or GITHUB_REPOSITORY)'); process.exit(1); }
424	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
425	  const stubPath = join(root, '.claudinite/shared/engine/scheduler/stubs/claudinite-scheduler.yml');
426	  if (!existsSync(stubPath)) { console.error(`converge-wiring: vendored stub not found at ${stubPath}`); process.exit(1); }
427	  const secretNames = await declaredSecrets(root, await repoConfig(root));
428	  const { changed, error } = await convergeWiring(root, fullName, readFileSync(stubPath, 'utf8'), secretNames, { badges, seedLocalPack });
429	  if (error) console.log(`! ${error}`);
430	  console.log(changed.length ? `converge-wiring: ${changed.join(', ')}` : 'converge-wiring: already converged');
431	}
432	
433	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
434

