1	// The PREWORK phase of task execution (task-prework DESIGN §3): the
2	// deterministic first phase, run as a SUBPROCESS before the agentic phase (when
3	// there is one) — code work, Action-side, over the one sanctioned non-MCP
4	// surface (the Action GITHUB_TOKEN, inherited in `env`). Prework and agentic
5	// work are similar, consecutive parts of one task execution; neither may decide
6	// to skip the run — that decision belongs to the precondition alone.
7	//
8	// The subprocess is the scheduler's child, so its `prework_timeout`
9	// is a HARD kill: a manual timer SIGKILLs an overrun and the run is reported
10	// failed. Its cwd is the TASK directory, so a declared `node worker.mjs` resolves
11	// to the script beside task.mjs (the containment the contract enforces); the repo
12	// root and slot context are handed in via CLAUDINITE_* env so the worker can act
13	// on the whole repo. Nothing the subprocess prints is threaded into the agent —
14	// prework communicates only through the repository (DESIGN §3).
15	//
16	// THE LOG IS NOT THAT CHANNEL. The child's output is ECHOED to the scheduler's own
17	// stdout/stderr as it arrives, so the Action log carries what the worker actually
18	// did. That is an observability decision, not a data channel: no agent reads the
19	// log, and §3's "communicate only through the repository" is untouched. It is echoed
20	// LIVE rather than dumped at exit for the case that needs it most — a worker SIGKILLed
21	// at its timeout, whose buffered output would otherwise die with it. Before this,
22	// a failed worker surfaced as a bare `preprocessing exited 1` plus a three-line
23	// stderr tail in an issue, and diagnosing one meant reproducing it by hand.
24	
25	import { spawn } from 'node:child_process';
26	import { existsSync, rmSync, readFileSync } from 'node:fs';
27	import { join } from 'node:path';
28	import { tmpdir } from 'node:os';
29	
30	// Run `command` as a subprocess bounded by `timeoutSeconds`. Resolves (never
31	// rejects) with { ok, timedOut, code, signal, stdout, stderr }: `ok` is a clean
32	// zero exit that did not time out. `taskDir` is the cwd; `env` is the full
33	// environment the child inherits (the caller injects GITHUB_TOKEN + CLAUDINITE_*).
34	// `echo` (default on) mirrors the child's output to this process as it arrives —
35	// injected rather than hardcoded so a test can capture it instead of polluting the
36	// test runner's own output.
37	export function runPrework(command, {
38	  taskDir, env, timeoutSeconds,
39	  echo = (chunk, stream) => (stream === 'stderr' ? process.stderr : process.stdout).write(chunk),
40	}) {
41	  return new Promise((resolve) => {
42	    const child = spawn(command, { cwd: taskDir, env, shell: true });
43	    let stdout = '';
44	    let stderr = '';
45	    let timedOut = false;
46	    // Echo is best-effort: a worker's output must never be the thing that fails the
47	    // run, so a broken sink is swallowed rather than propagated.
48	    const mirror = (chunk, stream) => { try { echo?.(String(chunk), stream); } catch { /* the run matters, the echo does not */ } };
49	    const timer = setTimeout(() => {
50	      timedOut = true;
51	      child.kill('SIGKILL'); // the hard kill — no grace period past the declared bound
52	    }, timeoutSeconds * 1000);
53	
54	    child.stdout?.on('data', (d) => { stdout += d; mirror(d, 'stdout'); });
55	    child.stderr?.on('data', (d) => { stderr += d; mirror(d, 'stderr'); });
56	    // A spawn error (command not found, etc.) is a failure, not a throw.
57	    child.on('error', (e) => {
58	      clearTimeout(timer);
59	      resolve({ ok: false, timedOut, code: null, signal: null, stdout, stderr: `${stderr}${e.message}` });
60	    });
61	    child.on('close', (code, signal) => {
62	      clearTimeout(timer);
63	      resolve({ ok: code === 0 && !timedOut, timedOut, code, signal, stdout, stderr });
64	    });
65	  });
66	}
67	
68	// The conditional-handoff signal (task-prework DESIGN §3, E4). A task with
69	// BOTH prework AND a non-`none` agent_model hands off to the agent
70	// ONLY when its worker requests it — so a task can absorb its work into
71	// prework and be AGENTLESS on the quiet nights. The scheduler hands the
72	// worker this path via CLAUDINITE_REQUEST_AGENT and files `ready-for-agent` iff
73	// the worker created it. It is a pure control signal: the worker communicates
74	// DATA to the agent only through the repository, never through this file (DESIGN
75	// §3, "no code→agent data channel"). The hand-off condition must name work
76	// prework COULD not do — never re-check whether the run should have happened;
77	// the precondition already decided that.
78	export function agentRequestPath({ pack, task, slotId }) {
79	  return join(tmpdir(), `claudinite-request-agent-${pack}-${task}-${slotId}`);
80	}
81	export function clearAgentRequest(path) { try { rmSync(path, { force: true }); } catch { /* nothing to clear */ } }
82	export function agentRequested(path) { return existsSync(path); }
83	
84	// …AND the artifacts that request refers to, plus why it was made. A worker writes
85	// JSON `{ delivered: { branch, pr, merged }, reason: { code, detail } }`, and the
86	// scheduler records both in the dispatch issue, which is where the agent reads them.
87	//
88	// This is the one thing that crosses the code→agent boundary as data (§3's named
89	// exception): identifiers for what this run created — a PR number, a branch ref — and
90	// the NAME of the condition that woke the agent. Never findings and never instructions:
91	// `reason.detail` says which gate fired and how many of what, and the findings
92	// themselves stay in the repo for the agent to re-run. Everything else still travels
93	// through the repository.
94	//
95	// Both keys are optional and their ABSENCE is meaningful, which is also what keeps an
96	// older vendored worker (one that predates a key) working: a worker that created
97	// nothing writes no `delivered` and the issue names none; a worker that does not know
98	// about `reason` writes none and the issue explains nothing, rather than asserting
99	// something false about why the agent is there.
100	export function readAgentRequest(path) {
101	  if (!existsSync(path)) return null;
102	  const raw = readFileSync(path, 'utf8').trim();
103	  if (!raw) return {};
104	  // A bare marker line (no payload) requests the agent and names no artifacts.
105	  try { return JSON.parse(raw); } catch { return {}; }
106	}
107	
108	// A one-line reason for the job summary / an issue comment when prework
109	// fails — distinguishing a timeout kill from a non-zero exit.
110	export function preworkFailure(result) {
111	  if (result.timedOut) return 'prework exceeded its prework_timeout and was killed';
112	  if (result.code !== null) return `prework exited ${result.code}`;
113	  return `prework could not run: ${result.stderr.trim().split('\n').pop() || 'unknown error'}`;
114	}
