    "id": "claudinite-isolation",
    "severity": "blocking",
    "failureMessage": "the vendored canon is refreshed nightly and refactored upstream — code that reaches into it inherits every canon rename as a breaking change",
    "fix": "inline the few lines you need into your own tree, remove the reference, or accept it with a reason in .claudinite-checks.json (rule \"claudinite-isolation\")",
    "relevantWhen": { "pathExists": ".claudinite/shared" },
    "forbidReferences": [
      {
        "from": ".",
        "to": ".claudinite",
        "matchUniqueFilenames": false,
        "except": [".claudinite", ".claude", ".github/workflows", ".gitignore", ".gitattributes", "CLAUDE.md", ".claudinite-checks.json"],
        "reason": "consumer files must not couple to the vendored canon — the wiring files are the reviewed exceptions (vendoring/DESIGN.md)"
      }
    ]
  },
  {
    "id": "scheduler-workflow-shape",
    "severity": "blocking",
    "failureMessage": "the scheduler is the repo's only cron and its slot math anchors on the hour — a drifted cron or a missing guard silently breaks staggering, double-run safety, or manual runs",
    "scanFiles": ".github/workflows/claudinite-scheduler.yml",
    "countMatchingLines": [
      {
        "linesMatching": "/\\bcron:\\s/",
        "atLeast": 1,
        "atMost": 1,
        "what": "declares {count} cron schedules, expected exactly one",
        "fix": "keep a single hourly cron — the scheduler is the repo's only cron"
      }
    ],
    "matchLines": [
      {
        "match": "/\\bcron:.*/",
        "unlessLineMatches": "/\\bcron:\\s*['\"]?(1[0-9]|[2-4][0-9]|50) \\* \\* \\* \\*['\"]?\\s*$/",
        "what": "{match} is not hourly on a fixed minute in :10\u2013:50",
        "fix": "use \"<minute> * * * *\" with a minute from 10 to 50 (bootstrap assigns it) — other crons collide with the :00 stampede or break the hourly slot math"
      }
    ],
    "checkEachFile": [
      {
        "require": "/^\\s*workflow_dispatch:/m",
        "what": "has no workflow_dispatch trigger",
        "fix": "add workflow_dispatch: so the scheduler can be run manually"
      },
      {
        "require": "/^\\s*concurrency:/m",
        "what": "has no concurrency group",
        "fix": "add a concurrency: group so overlapping runs serialize (double-run safety)"
      },
      {
        "require": "/engine\\/scheduler\\/run\\.mjs/",
        "what": "does not run the vendored engine entry",
        "fix": "the job must run node .claudinite/shared/engine/scheduler/run.mjs — all logic lives in the vendored engine, not the workflow"
      },
      {
        "require": "/^\\s*contents:\\s*write\\b/m",
        "what": "does not grant contents: write",
        "fix": "set permissions.contents: write — the update runner pushes its delivery branch; without it the self-refresh 403s"
      },
=== gha
          "/uses:\\s*actions\\/upload-pages-artifact/",
          "/^\\s*path:\\s*['\"]?\\.\\/?['\"]?\\s*$/m"
        ],
        "require": "/\\brm\\b[^\\n]*\\.claude/",
        "what": "uploads the repo root (path: .) to actions/upload-pages-artifact with no step pruning .claude/ — its skills/* symlinks dangle in CI and the tar fails",
        "fix": "add a step before the upload that prunes the agent tooling: `run: rm -rf .claude .claudinite` (never part of a published site)"
      }
    ]
  },
  {
    "id": "gha/no-scheduled-fleet-executor",
    "severity": "blocking",
    "failureMessage": "a second cron competes with the one schedule the repo is meant to have — the per-repo scheduler, which owns every recurring Claudinite job",
    "scanFiles": "/^\\.github\\/workflows\\/[^/]+\\.ya?ml$/",
    "scanTracked": true,
    "excludeFiles": ".github/workflows/claudinite-scheduler.yml",
    "checkEachFile": [
      {
        "relevantWhen": { "pathExists": ".github/workflows/claudinite-scheduler.yml" },
        "forbid": "/^\\s*schedule:/m",
        "what": "carries a `schedule:` trigger, but the vendored claudinite-scheduler.yml is this repo's only permitted cron",
        "fix": "port this workflow's steps into the scheduler task that owns the work and delete the workflow in the same commit (per-project-scheduling §3)"
      },
      {
        "relevantWhen": { "pathAbsent": ".github/workflows/claudinite-scheduler.yml" },
        "whenFileMatches": "/uses:\\s*\\S*\\/Claudinite\\/\\.github\\/workflows\\//i",
        "forbid": "/^\\s*schedule:/m",
        "what": "a Claudinite executor (it calls a canon reusable workflow) carries a `schedule:` trigger",
        "fix": "remove the schedule: trigger — make it workflow_dispatch only, and adopt the vendored claudinite-scheduler.yml, which owns every recurring Claudinite job (packs/core/scheduled-tasks.md)"
      }
    ]
  }
]

