+
+// The claim comment's marker and its parse. The comment carries WHO and WHEN —
+// the executor id and its run URL — because executor identity is an unbounded set
+// and must never become a label (DESIGN §4).
+export const CLAIM_MARKER = '<!-- claudinite-claim -->';
+export const HANDOFF_MARKER = '<!-- claudinite-handoff -->';
+export const EPISODE_MARKER = '<!-- claudinite-episode -->';
