        if (res.status >= 200 && res.status < 300) {
          return { ok: true, sessionId: json?.id ?? json?.session_id ?? null };
        }
        lastError = `endpoint "${endpoint.name}" returned ${res.status}${json?.error ? `: ${JSON.stringify(json.error)}` : ''}`;
