export const SESSION_SCOPES = ['self', 'fleet'];

// What must happen to a task's work item when a recovery path would re-execute it
// (tasks-dispatch DESIGN §6). `requeue` is the safe-side default for sweep-shaped
// work; `needs-human` is the at-most-once dial a one-shot side effect declares.
export const INTERRUPT_POLICIES = ['requeue', 'needs-human'];

// F17, enforced at author time rather than left to a convention: a prework legally
// allowed to outlive the executing leash would be RECLAIMED WHILE ALIVE, and the
// failure is not one duplicate run but a livelock — every tenure reclaimed before
// it can finish, prework re-executing each cycle, the occurrence never converging.
// The leash is the engine's, so the comparison belongs here, where a declaration is
// judged, and not in a repo's wiring.
const EXECUTING_LEASH_SECONDS = 3600;

