1	// The two operator levers (tasks-dispatch DESIGN §8), which are the whole of
2	// urgency, forcing, fan-out and retry:
3	//
4	//   create-work-item <pack>/<task> [--urgent] [--context …] [--not-before ISO]
5	//                                  [--blocked-by #N,#M] [--qualifier text]
6	//                                  [--supersedes #N]
7	//   create-work-item --wake <#N> [--urgent]
8	//
9	// FORCING A SCHEDULED TASK IS WAKING ITS STANDING ITEM — strip `task:blocked`,
10	// clear `Not-before`, optionally add `task:urgent`. The same lever as the human
11	// re-queue out of `needs-human`, which is no accident: "run this now" and "retry
12	// this now" are the same operation on the same object. The executor still
13	// evaluates the precondition at pick, so a force that finds no work SAYS so where
14	// the operator reads it. `FORCE_TASKS`, the forced-verdict path, the `~f` marker
15	// and the watermark exclusion all reduce to these two levers.
16	//
17	// FORCING AD-HOC WORK IS CREATING AN ITEM — a parameterized run, a `manual` task,
18	// a fan-out target. It carries no `origin:schedule`, so it is invisible to the
19	// tick's guards in both directions: it neither suppresses tomorrow's occurrence
20	// nor consumes it.
21	
22	import { pathToFileURL } from 'node:url';
23	import {
24	  READY, BLOCKED, URGENT, NEEDS_HUMAN, OUTCOME_OBSOLETE, QUEUE_LABELS,
25	  EPISODE_MARKER, workItemTitle, workItemBody, withNotBefore, hasLabel,
26	} from './work-item.mjs';
27	
28	// The Context a hand-created item carries when the operator names none. Generic
29	// on purpose — it names the mechanism, not the task — because an item's Context is
30	// the agent's binding scope, and a forced item that carried none would read as a
31	// scope of nothing.
32	export const FORCED_CONTEXT =
33	  'Created by hand — no precondition asserts there is work to do. Do only what the task file specifies, and converge to a no-op if there is nothing.';
34	
35	export function parseArgs(argv) {
36	  const out = { urgent: false, context: [], blockedBy: [], notBefore: null, qualifier: null, supersedes: null, wake: null, target: null };
37	  for (let i = 0; i < argv.length; i += 1) {
38	    const a = argv[i];
39	    const next = () => argv[++i];
40	    if (a === '--urgent') out.urgent = true;
41	    else if (a === '--wake') out.wake = Number(String(next()).replace('#', ''));
42	    else if (a === '--context') out.context.push(next());
43	    else if (a === '--not-before') out.notBefore = next();
44	    else if (a === '--qualifier') out.qualifier = next();
45	    else if (a === '--supersedes') out.supersedes = Number(String(next()).replace('#', ''));
46	    else if (a === '--blocked-by') out.blockedBy.push(...String(next()).split(',').map((s) => Number(s.trim().replace('#', ''))).filter(Boolean));
47	    else if (!a.startsWith('--')) out.target = a;
48	  }
49	  return out;
50	}
51	
52	// Wake an item: clear its wait and put it back in the queue. Also the sanctioned
53	// road back from `needs-human` — nothing MECHANICAL ever re-queues a triage item,
54	// and the next pickup re-runs the precondition, which is what makes the retry safe
55	// even when the failed run half-did its work.
56	export async function wakeItem(gh, repo, number, { urgent = false } = {}) {
57	  const api = await import('../github.mjs');
58	  const issue = await api.readIssue(gh, repo, number);
59	  if (!issue) return { ok: false, error: `#${number} could not be read` };
60	  const body = withNotBefore(issue.body ?? '', null);
61	  if (body !== issue.body) await gh(`/repos/${repo}/issues/${number}`, { method: 'PATCH', body: { body } });
62	  // The episode boundary: every claim before this moment is dead, and arbitrating
63	  // over dead claims is what livelocks an item through reclaim cycles forever.
64	  await api.comment(gh, repo, number, `${EPISODE_MARKER}\nWoken by hand — cleared \`Not-before\` and returned this item to the queue.`);
65	  for (const l of [BLOCKED, NEEDS_HUMAN]) if (hasLabel(issue, l)) await api.removeLabel(gh, repo, number, l);
66	  await api.addLabel(gh, repo, number, READY);
67	  if (urgent) await api.addLabel(gh, repo, number, URGENT);
68	  return { ok: true, number };
69	}
70	
71	export async function createWorkItem(gh, repo, { pack, task, taskPath, opts, log = console.log }) {
72	  const api = await import('../github.mjs');
73	  const { listOpenWorkItems } = await import('./read.mjs');
74	  const title = workItemTitle({ pack, task, qualifier: opts.qualifier });
75	
76	  // The pick-time mutex means a new item QUEUES behind an open twin rather than
77	  // running beside it, and the operator should know they are queueing, not jumping.
78	  const twin = (await listOpenWorkItems(gh, repo)).find((i) => (i.title ?? '').trim() === title);
79	  if (twin) log(`! #${twin.number} is an open item with this exact title — the new item will queue behind it, not run beside it`);
80	
81	  await api.ensureLabels(gh, repo, QUEUE_LABELS);
82	  const blocked = opts.notBefore !== null || opts.blockedBy.length > 0;
83	  const res = await api.createIssue(gh, repo, {
84	    title,
85	    body: workItemBody({
86	      taskPath,
87	      notBefore: opts.notBefore,
88	      blockedBy: opts.blockedBy,
89	      context: opts.context.length ? opts.context : [FORCED_CONTEXT],
90	    }),
91	    labels: [blocked ? BLOCKED : READY, ...(opts.urgent ? [URGENT] : [])],
92	  });
93	  if (!res.number) return { ok: false, error: `could not create the item: ${res.status}` };
94	
95	  if (opts.supersedes) {
96	    await api.comment(gh, repo, opts.supersedes, `Superseded by #${res.number}, a retry of this work created by hand.`);
97	    await api.addLabel(gh, repo, opts.supersedes, OUTCOME_OBSOLETE);
98	    await api.closeIssue(gh, repo, opts.supersedes, 'not_planned');
99	  }
100	  return { ok: true, number: res.number };
101	}
102	
103	async function main() {
104	  const { makeGh, actionRepoContext } = await import('../signals/gh.mjs');
105	  const { discoverTasks } = await import('../discover.mjs');
106	  const { loadConfig } = await import('../../checks/helpers/repo-context.mjs');
107	
108	  const opts = parseArgs(process.argv.slice(2));
109	  const { repo } = actionRepoContext();
110	  if (!repo) { console.error('GITHUB_REPOSITORY not set'); process.exit(1); }
111	  const gh = makeGh();
112	
113	  if (opts.wake) {
114	    const res = await wakeItem(gh, repo, opts.wake, { urgent: opts.urgent });
115	    if (!res.ok) { console.error(res.error); process.exit(1); }
116	    console.log(`woke #${opts.wake}${opts.urgent ? ' (urgent)' : ''}`);
117	    return;
118	  }
119	  if (!opts.target || !opts.target.includes('/')) {
120	    console.error('usage: create-work-item <pack>/<task> [--urgent] [--context …] [--not-before ISO] [--blocked-by #N] [--qualifier text] [--supersedes #N]\n       create-work-item --wake <#N> [--urgent]');
121	    process.exit(1);
122	  }
123	  const [pack, task] = opts.target.split('/');
124	  const root = process.cwd();
125	  const { tasks } = await discoverTasks(root, loadConfig(root));
126	  const found = tasks.find((t) => t.pack === pack && t.id === task);
127	  if (!found) { console.error(`no task "${opts.target}" in this repo's declared packs`); process.exit(1); }
128	
129	  const res = await createWorkItem(gh, repo, { pack, task, taskPath: found.taskPath, opts });
130	  if (!res.ok) { console.error(res.error); process.exit(1); }
131	  console.log(`created #${res.number} ${opts.target}${opts.urgent ? ' (urgent)' : ''}`);
132	}
133	
134	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
135	  main().catch((e) => { console.error(e); process.exit(1); });
136	}

