export function withDeclaredSecrets(stubText, names = []) {
  if (!names.length) return stubText;
  const lines = names.map((n) => `          ${n}: \${{ secrets.${n} }}`).join('\n');
  return stubText.replace(/^(\s*GITHUB_TOKEN: \$\{\{ github\.token \}\})$/m, `$1\n${lines}`);
}

