  const s = mostRecentSlot('hourly', D, '2026-07-22T14:37:11Z');
  assert.equal(s.id, 'h2026-07-22T14Z');
  assert.equal(s.time.toISOString(), '2026-07-22T14:00:00.000Z');
});

