1	// The executor loop end to end against a fake GitHub — pick, claim, evaluate,
2	// prework, hand off, converge. The pure rules are tested beside this; what this
3	// pins is that the SHELL actually drives them to a terminal state, which is the
4	// thing a fixture over the rules alone can never say.
5	
6	import { test } from 'node:test';
7	import assert from 'node:assert/strict';
8	import { runExecutor } from '../../../engine/scheduler/queue/executor.mjs';
9	import { parseWorkItemBody } from '../../../engine/scheduler/queue/work-item.mjs';
10	
11	const SCHEDULE = { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 };
12	const CONFIG = { taskScheduler: SCHEDULE, packConfig: {} };
13	
14	// A fake repo: issues with labels, bodies, comments and state, driven through the
15	// same REST paths the shell calls.
16	function fakeRepo(issues = []) {
17	  const state = { issues: issues.map((i) => ({ comments: [], state: 'open', ...i })), commentSeq: 100, calls: [] };
18	  const find = (n) => state.issues.find((i) => i.number === n);
19	  const gh = async (path, { method = 'GET', body } = {}) => {
20	    state.calls.push(`${method} ${path}`);
21	    let m;
22	    if (method === 'GET' && /^\/repos\/[^/]+\/[^/]+\/issues\?/.test(path)) {
23	      const page = Number(/[?&]page=(\d+)/.exec(path)?.[1] ?? 1); // NOT /page=/ — that matches per_page
24	      return { status: 200, json: page === 1 ? state.issues.filter((i) => i.state === 'open') : [] };
25	    }
26	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/comments/.exec(path))) {
27	      const issue = find(Number(m[1]));
28	      if (method === 'POST') {
29	        issue.comments.push({ id: (state.commentSeq += 1), body: body.body });
30	        issue.updated_at = 'now';
31	        return { status: 201, json: {} };
32	      }
33	      return { status: 200, json: issue.comments };
34	    }
35	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/labels\/(.+)$/.exec(path))) {
36	      const issue = find(Number(m[1]));
37	      issue.labels = issue.labels.filter((l) => l !== decodeURIComponent(m[2]));
38	      return { status: 200, json: {} };
39	    }
40	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/labels$/.exec(path))) {
41	      const issue = find(Number(m[1]));
42	      issue.labels.push(...body.labels);
43	      return { status: 200, json: {} };
44	    }
45	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)$/.exec(path))) {
46	      const issue = find(Number(m[1]));
47	      if (method === 'PATCH') Object.assign(issue, body);
48	      return { status: 200, json: issue };
49	    }
50	    return { status: 404, json: null };
51	  };
52	  return { state, gh, find };
53	}
54	
55	const workItem = (number, task, labels, body = null) => ({
56	  number, title: `[claudinite-work] p/${task}`, labels,
57	  body: body ?? `packs/p/tasks/${task}/task.md\n\nExecute the Claudinite task above.\n`,
58	  created_at: '2026-08-14T04:00:00Z', updated_at: '2026-08-14T04:00:00Z',
59	});
60	
61	const task = (id, decl = {}) => ({
62	  pack: 'p', id, taskDir: `packs/p/tasks/${id}`, taskPath: `packs/p/tasks/${id}/task.md`,
63	  decl: { id, frequency: 'daily', agent_model: 'sonnet', precondition: () => ({ run: true }), ...decl },
64	});
65	
66	const drive = (repo, tasks, over = {}) => runExecutor({
67	  gh: repo.gh, repo: 'o/r', root: '/tmp', config: CONFIG, tasks,
68	  executorId: 'E1', maxItems: 2, now: () => new Date('2026-08-14T04:20:00Z'),
69	  collectSignalsFor: async () => ({}),
70	  runTaskPrework: async () => ({ ok: true, agentRequested: false }),
