44	  const stale = staleReadyItems(open, now, { periodFor: periodForTasks(tasks) });
45	  const deadAgents = deadAgentItems(open, now);
46	  const stuck = stuckBlockedItems(open, now, { stateOf: (n) => known.get(n) ?? null });
