86	    + `${count(EXECUTING)} executing, ${count(AGENT)} with an agent, `
87	    + `${open.filter((i) => hasLabel(i, NEEDS_HUMAN)).length + converged.size} needs-human; `
88	    + `this run escalated ${result.staleReady.length} stale, reclaimed ${result.deadAgents.length} dead agent claim(s), `
