1	// The janitor's sweep over the WORK-ITEM QUEUE (tasks-dispatch DESIGN §11) — the
2	// half of this task that runs where `taskScheduler.dispatch` is `"queue"`.
3	//
4	// It shrinks twice over against the slot-mechanism sweep beside it. The re-arm and
5	// its grace window are GONE: an executor polls on the tick's cron, so a lost label
6	// event is latency and never the only delivery. And the executing-leash reclaim
7	// moved to the TICK — a deterministic label rule, serialized and hourly, which
8	// recovers a dead executor's item in ~2h instead of ~25h.
9	//
10	// What is left is everything needing judgment or a longer horizon: the dead agent
11	// claim, the stale-ready escalation, the stuck-dependency sweep (comment only —
12	// the item still proceeds by itself the moment its blockers resolve), the
13	// stateless-item repair, and a health review that can now be computed from issues.
14	//
15	// This file is the I/O shell; every verdict is a pure rule in the vendored engine,
16	// so what counts as stale, dead or stuck is decided in exactly one place.
17	
18	import {
19	  staleReadyItems, staleReadyComment, deadAgentItems, deadAgentComment,
20	  stuckBlockedItems, stuckBlockedComment, statelessItems, statelessComment,
21	  periodForTasks,
22	} from '../../../../engine/scheduler/queue/janitor-rules.mjs';
23	import {
24	  READY, AGENT, EXECUTING, BLOCKED, NEEDS_HUMAN, QUEUE_LABELS, HANDOFF_MARKER,
25	  parseWorkItemBody, hasLabel,
26	} from '../../../../engine/scheduler/queue/work-item.mjs';
27	import { listOpenWorkItems } from '../../../../engine/scheduler/queue/read.mjs';
28	import { ensureLabels, addLabel, removeLabel, comment, listComments } from '../../../../engine/scheduler/github.mjs';
29	
30	export async function sweepQueue(gh, repo, now, { tasks = [], log = console.log } = {}) {
31	  const open = await listOpenWorkItems(gh, repo);
32	  const result = { open: open.length, staleReady: [], deadAgents: [], stuck: [], stateless: [] };
33	
34	  // A `Blocked-by` target need not be a work item, so its state is read directly.
35	  const known = new Map(open.map((i) => [i.number, i.state]));
36	  for (const i of open) {
37	    for (const n of parseWorkItemBody(i.body).blockedBy) {
38	      if (known.has(n)) continue;
39	      const res = await gh(`/repos/${repo}/issues/${n}`);
40	      known.set(n, res.status === 200 ? res.json?.state ?? null : null);
41	    }
42	  }
43	
44	  const stale = staleReadyItems(open, now, { periodFor: periodForTasks(tasks) });
45	  const deadAgents = deadAgentItems(open, now);
46	  const stuck = stuckBlockedItems(open, now, { stateOf: (n) => known.get(n) ?? null });
47	  const stateless = statelessItems(open);
48	
49	  if (stale.length || deadAgents.length || stateless.length) await ensureLabels(gh, repo, QUEUE_LABELS);
50	
51	  const escalate = async (item, body, dropLabel) => {
52	    await comment(gh, repo, item.number, body);
53	    if (dropLabel) await removeLabel(gh, repo, item.number, dropLabel);
54	    await addLabel(gh, repo, item.number, NEEDS_HUMAN);
55	  };
56	
57	  for (const item of stale) {
58	    await escalate(item, staleReadyComment(item), READY);
59	    log(`escalated stale-ready #${item.number} → ${NEEDS_HUMAN}`);
60	    result.staleReady.push(item.number);
61	  }
62	  for (const item of deadAgents) {
63	    await escalate(item, deadAgentComment(item, await sessionNote(gh, repo, item)), AGENT);
64	    log(`reclaimed a dead agent claim on #${item.number} → ${NEEDS_HUMAN}`);
65	    result.deadAgents.push(item.number);
66	  }
67	  for (const item of stuck) {
68	    // COMMENT ONLY, deliberately: labels untouched means the item still proceeds
69	    // by itself the moment its blockers resolve, and a human who decides it is
70	    // dead closes it by hand.
71	    const unresolved = parseWorkItemBody(item.body).blockedBy.filter((n) => known.get(n) !== 'closed');
72	    await comment(gh, repo, item.number, stuckBlockedComment(item, unresolved));
73	    log(`surfaced stuck dependency on #${item.number} (blocked by ${unresolved.map((n) => `#${n}`).join(', ')})`);
74	    result.stuck.push(item.number);
75	  }
76	  for (const item of stateless) {
77	    await escalate(item, statelessComment(), null);
78	    log(`repaired stateless #${item.number} → ${NEEDS_HUMAN}`);
79	    result.stateless.push(item.number);
80	  }
81	
82	  // The health review — the queue as its subject, computable entirely from issues.
83	  const converged = new Set([...result.staleReady, ...result.deadAgents, ...result.stateless]);
84	  const count = (label) => open.filter((i) => hasLabel(i, label) && !converged.has(i.number)).length;
85	  log(`health: ${result.open} open work item(s) — ${count(BLOCKED)} blocked, ${count(READY)} ready, `
86	    + `${count(EXECUTING)} executing, ${count(AGENT)} with an agent, `
87	    + `${open.filter((i) => hasLabel(i, NEEDS_HUMAN)).length + converged.size} needs-human; `
88	    + `this run escalated ${result.staleReady.length} stale, reclaimed ${result.deadAgents.length} dead agent claim(s), `
89	    + `surfaced ${result.stuck.length} stuck dependency(ies), repaired ${result.stateless.length} stateless item(s)`);
90	  return result;
91	}
92	
93	// The hand-off comment names the session, so the escalation can say WHICH one
94	// died rather than merely that one did. Absent (a torn hand-off), the escalation
95	// says less rather than asserting something it does not know.
96	async function sessionNote(gh, repo, item) {
97	  const handoff = (await listComments(gh, repo, item.number))
98	    .filter((c) => (c.body ?? '').includes(HANDOFF_MARKER)).at(-1);
99	  const nonce = handoff?.body?.match(/nonce `([^`]+)`/)?.[1];
100	  return nonce ? `invocation nonce ${nonce}` : null;
101	}

